use anyhow::{bail, ensure, Result};
use mdbook_dada::{
    evidence::{self, ReviewBundle},
    inventory::{find_root, Inventory},
};
use std::path::Path;

fn run() -> Result<bool> {
    let mut args = std::env::args().skip(1);
    let command = args.next().unwrap_or_else(|| "status".into());
    let root = find_root(&std::env::current_dir()?)?;
    let inventory = Inventory::load(&root)?;
    match command.as_str() {
        "check" | "status" => {
            let rest: Vec<_> = args.collect();
            ensure!(rest.is_empty() || rest == ["--explain"], "usage: dada-spec {command} [--explain]");
            let report = evidence::check(&inventory)?;
            for status in &report.statuses {
                println!("{}: inputs={}, correspondence={}, mechanical={}", status.unit, status.evidence, status.correspondence, status.mechanical);
            }
            if !report.is_ok() { eprint!("{}", report.render(&inventory)); }
            Ok(report.is_ok())
        }
        "prepare" => {
            let id = args.next().ok_or_else(|| anyhow::anyhow!("usage: dada-spec prepare <unit-id> [--input <file>]..."))?;
            let mut extras = Vec::new();
            while let Some(option) = args.next() {
                ensure!(option == "--input", "unknown prepare option {option}");
                extras.push(args.next().ok_or_else(|| anyhow::anyhow!("--input requires a project-relative file"))?);
            }
            let bundle = ReviewBundle::prepare(&inventory, &id, &extras)?;
            let path = evidence::save_bundle(&inventory, &bundle)?;
            println!("{}", path.display());
            println!("Prepared {} inputs. No review has been recorded. Follow md/repo/correspondence-review.md.", bundle.inputs.len());
            Ok(true)
        }
        "record" => {
            let rest: Vec<_> = args.collect();
            ensure!(rest.len() == 2, "usage: dada-spec record <bundle.json> <review.json>");
            let bundle = evidence::load_bundle(Path::new(&rest[0]))?;
            let review = evidence::load_review(Path::new(&rest[1]))?;
            println!("{}", evidence::record(&inventory, &bundle, &review)?.display());
            Ok(true)
        }
        _ => bail!("usage: dada-spec check | status [--explain] | prepare <unit-id> [--input <file>]... | record <bundle.json> <review.json>"),
    }
}

fn main() {
    match run() {
        Ok(true) => {}
        Ok(false) => std::process::exit(1),
        Err(error) => {
            eprintln!("{}", evidence::format_error(&error));
            std::process::exit(1);
        }
    }
}

//! Syntactic evidence validation. This module never invokes an agent or proof checker.
use crate::inventory::{hash, Input, Inventory, SCHEMA};
use annotate_snippets::{AnnotationKind, Group, Level, Renderer, Snippet};
use anyhow::{ensure, Context, Result};
use serde::{Deserialize, Serialize};
use std::{
    collections::{BTreeMap, BTreeSet},
    fs,
    io::Write,
    path::{Path, PathBuf},
};

#[derive(Clone, Debug, Serialize, Deserialize)]
#[serde(deny_unknown_fields)]
pub struct ReviewBundle {
    pub schema: u32,
    pub unit: String,
    pub inputs: Vec<Input>,
    pub digest: String,
}

impl ReviewBundle {
    pub fn prepare(inventory: &Inventory, unit: &str, extra: &[String]) -> Result<Self> {
        let mut inputs = inventory.inputs(unit)?;
        for path in extra {
            inputs.push(inventory.extra_input(path)?);
        }
        inputs.sort_by(|a, b| a.key.cmp(&b.key));
        let mut bundle = Self {
            schema: SCHEMA,
            unit: unit.to_owned(),
            inputs,
            digest: String::new(),
        };
        bundle.digest = bundle.content_digest()?;
        ensure!(
            bundle.integrity_errors().is_empty(),
            "duplicate inputs in bundle"
        );
        Ok(bundle)
    }

    fn content_digest(&self) -> Result<String> {
        // Locations are retrieval aids, not identity: moving a Markdown block
        // without changing it need not stale a review. Paths and exact content do.
        let identities: Vec<_> = self
            .inputs
            .iter()
            .map(|input| (&input.key, &input.path, &input.sha256))
            .collect();
        Ok(hash(&serde_json::to_vec(&(
            self.schema,
            &self.unit,
            identities,
        ))?))
    }

    fn integrity_errors(&self) -> Vec<String> {
        let mut errors = Vec::new();
        if self.schema != SCHEMA {
            errors.push(format!("unsupported bundle schema {}", self.schema));
        }
        if self.content_digest().ok().as_ref() != Some(&self.digest) {
            errors.push("bundle digest does not match its input manifest".into());
        }
        let mut seen = BTreeSet::new();
        for input in &self.inputs {
            if !seen.insert(&input.key) {
                errors.push(format!("duplicate input {}", input.key));
            }
            if hash(input.content.as_bytes()) != input.sha256 {
                errors.push(format!("snapshot hash does not match {}", input.key));
            }
            if input.line == 0 {
                errors.push(format!("invalid source line for {}", input.key));
            }
        }
        errors
    }
}

#[derive(Clone, Copy, Debug, Serialize, Deserialize, PartialEq, Eq)]
#[serde(rename_all = "snake_case")]
pub enum Conclusion {
    Corresponds,
    Mismatch,
    Inconclusive,
}

#[derive(Clone, Debug, Serialize, Deserialize)]
#[serde(deny_unknown_fields)]
pub struct ReviewRecord {
    pub schema: u32,
    pub bundle: String,
    pub reviewer: String,
    pub provenance: String,
    pub examined: Vec<String>,
    pub conclusion: Conclusion,
    pub rationale: String,
    pub limitations: Vec<String>,
    #[serde(default)]
    pub supersedes: Vec<String>,
}

impl ReviewRecord {
    pub fn digest(&self) -> Result<String> {
        Ok(hash(&serde_json::to_vec(self)?))
    }
}

/// Compare against the independently derived inventory, not a self-declared
/// checklist. Extra inputs are allowed only as current project file snapshots.
pub fn validate_bundle(inventory: &Inventory, bundle: &ReviewBundle) -> Result<Vec<String>> {
    let mut errors = bundle.integrity_errors();
    let mut expected: BTreeMap<_, _> = inventory
        .inputs(&bundle.unit)?
        .into_iter()
        .map(|input| (input.key.clone(), input))
        .collect();
    for input in &bundle.inputs {
        if let Some(path) = input.key.strip_prefix("extra:") {
            match inventory.extra_input(path) {
                Ok(extra) => {
                    expected.insert(extra.key.clone(), extra);
                }
                Err(error) => errors.push(format!("cannot resolve {}: {error:#}", input.key)),
            }
        }
    }
    let actual: BTreeMap<_, _> = bundle
        .inputs
        .iter()
        .map(|input| (&input.key, input))
        .collect();
    for (key, input) in &expected {
        match actual.get(key) {
            None => errors.push(format!("missing required input {key}")),
            Some(saved)
                if saved.content != input.content
                    || saved.sha256 != input.sha256
                    || saved.path != input.path =>
            {
                errors.push(format!("stale or substituted input {key}"))
            }
            _ => {}
        }
    }
    for key in actual.keys() {
        if !expected.contains_key(*key) {
            errors.push(format!(
                "unexpected input {key}; add consulted files with prepare --input"
            ));
        }
    }
    Ok(errors)
}

pub fn validate_review(bundle: &ReviewBundle, review: &ReviewRecord) -> Vec<String> {
    let mut errors = Vec::new();
    if review.schema != SCHEMA {
        errors.push(format!("unsupported review schema {}", review.schema));
    }
    if review.bundle != bundle.digest {
        errors.push("review names a different bundle".into());
    }
    for (field, value) in [
        ("reviewer", &review.reviewer),
        ("provenance", &review.provenance),
        ("rationale", &review.rationale),
    ] {
        if value.trim().is_empty() {
            errors.push(format!("review requires a nonempty {field}"));
        }
    }
    if review
        .limitations
        .iter()
        .any(|entry| entry.trim().is_empty())
    {
        errors.push("limitations must not contain empty entries".into());
    }
    let examined: BTreeSet<_> = review.examined.iter().collect();
    if examined.len() != review.examined.len() {
        errors.push("duplicate examined input".into());
    }
    for input in &bundle.inputs {
        if input.requires_examination() && !examined.contains(&input.key) {
            errors.push(format!(
                "review did not examine required input {}",
                input.key
            ));
        }
    }
    for key in examined {
        if !bundle.inputs.iter().any(|input| &input.key == key) {
            errors.push(format!("examined input is not in bundle: {key}"));
        }
    }
    let supersedes: BTreeSet<_> = review.supersedes.iter().collect();
    if supersedes.len() != review.supersedes.len() {
        errors.push("duplicate superseded review".into());
    }
    errors
}

fn read_json<T: for<'de> Deserialize<'de>>(path: &Path) -> Result<T> {
    serde_json::from_slice(&fs::read(path).with_context(|| format!("reading {}", path.display()))?)
        .with_context(|| format!("parsing {}", path.display()))
}

fn write_immutable<T: Serialize>(root: &Path, relative: &Path, value: &T) -> Result<PathBuf> {
    let path = root.join(relative);
    let parent = path.parent().context("artifact has no parent")?;
    fs::create_dir_all(parent)?;
    ensure!(
        parent.canonicalize()?.starts_with(root),
        "evidence output escapes project"
    );
    let mut bytes = serde_json::to_vec_pretty(value)?;
    bytes.push(b'\n');
    if path.exists() {
        ensure!(
            !fs::symlink_metadata(&path)?.file_type().is_symlink(),
            "evidence output is a symbolic link"
        );
        ensure!(
            fs::read(&path)? == bytes,
            "immutable evidence differs at {}",
            path.display()
        );
    } else {
        fs::OpenOptions::new()
            .write(true)
            .create_new(true)
            .open(&path)?
            .write_all(&bytes)?;
    }
    Ok(path)
}

pub fn save_bundle(inventory: &Inventory, bundle: &ReviewBundle) -> Result<PathBuf> {
    let current = Inventory::load(&inventory.root)?;
    let inventory = &current;
    let errors = validate_bundle(inventory, bundle)?;
    ensure!(
        errors.is_empty(),
        "cannot save bundle: {}",
        errors.join("; ")
    );
    let relative = PathBuf::from("evidence/bundles").join(format!("{}.json", bundle.digest));
    let existing = inventory.root.join(&relative);
    if existing.exists() {
        ensure!(
            existing.canonicalize()?.starts_with(&inventory.root),
            "evidence output escapes project"
        );
        let saved: ReviewBundle = read_json(&existing)?;
        ensure!(
            saved.digest == bundle.digest && validate_bundle(inventory, &saved)?.is_empty(),
            "stored bundle is inconsistent"
        );
        // Same inputs at new source line numbers reuse the original snapshot.
        return Ok(existing);
    }
    write_immutable(&inventory.root, &relative, bundle)
}

/// Record a review only after checking the same current input set used by check.
/// Recording a mismatch is permitted and will cause required review checks to fail.
pub fn record(
    inventory: &Inventory,
    bundle: &ReviewBundle,
    review: &ReviewRecord,
) -> Result<PathBuf> {
    let current = Inventory::load(&inventory.root)?;
    let inventory = &current;
    let mut errors = validate_bundle(inventory, bundle)?;
    errors.extend(validate_review(bundle, review));
    ensure!(
        errors.is_empty(),
        "cannot record review: {}",
        errors.join("; ")
    );
    for previous in &review.supersedes {
        ensure!(valid_digest(previous), "invalid superseded review digest");
        let old: ReviewRecord = read_json(
            &inventory
                .root
                .join("evidence/records")
                .join(&bundle.unit)
                .join(format!("{previous}.json")),
        )?;
        ensure!(
            old.digest()? == *previous,
            "superseded review contents differ"
        );
        let prior: ReviewBundle = read_json(
            &inventory
                .root
                .join("evidence/bundles")
                .join(format!("{}.json", old.bundle)),
        )?;
        ensure!(
            prior.unit == bundle.unit,
            "superseded review must concern the same unit"
        );
    }
    save_bundle(inventory, bundle)?;
    write_immutable(
        &inventory.root,
        &PathBuf::from("evidence/records")
            .join(&bundle.unit)
            .join(format!("{}.json", review.digest()?)),
        review,
    )
}

fn valid_digest(value: &str) -> bool {
    value.len() == 64
        && value
            .bytes()
            .all(|byte| byte.is_ascii_hexdigit() && !byte.is_ascii_uppercase())
}

#[derive(Debug)]
pub struct Issue {
    pub unit: Option<String>,
    pub message: String,
    pub details: Vec<String>,
}

#[derive(Debug)]
pub struct UnitStatus {
    pub unit: String,
    pub evidence: &'static str,
    pub correspondence: &'static str,
    pub mechanical: &'static str,
}

#[derive(Debug, Default)]
pub struct Report {
    pub statuses: Vec<UnitStatus>,
    pub issues: Vec<Issue>,
}

impl Report {
    pub fn is_ok(&self) -> bool {
        self.issues.is_empty()
    }

    pub fn render(&self, inventory: &Inventory) -> String {
        let mut result = String::new();
        for issue in &self.issues {
            let mut group = Group::with_title(Level::ERROR.primary_title(&issue.message));
            if let Some(unit) = issue.unit.as_ref().and_then(|id| inventory.units.get(id)) {
                let source = &inventory.sources[&unit.source_path];
                // Highlight the header/options, keeping the complete authored body
                // available but avoiding enormous math snippets in diagnostics.
                let header_end = source[unit.range.start..unit.range.end]
                    .find("\n\n")
                    .map_or(unit.range.end, |end| unit.range.start + end);
                group = group.element(
                    Snippet::source(source)
                        .path(&unit.source_path)
                        .fold(true)
                        .annotation(
                            AnnotationKind::Primary
                                .span(unit.range.start..header_end)
                                .label("evidence required for this unit"),
                        ),
                );
            }
            let mut groups = vec![group];
            for detail in issue.details.iter().take(8) {
                groups.push(Group::with_title(Level::NOTE.secondary_title(detail)));
            }
            if let Some(unit) = &issue.unit {
                groups.push(Group::with_title(Level::HELP.secondary_title(format!(
                    "run `cargo run -p mdbook-dada --bin dada-spec -- prepare {unit}`, review the packet, then use `dada-spec record <bundle> <review>`"))));
            }
            groups.push(Group::with_title(Level::HELP.secondary_title("follow md/repo/correspondence-review.md; do not refresh hashes without reviewing changed inputs")));
            result.push_str(&Renderer::plain().render(&groups));
            result.push('\n');
        }
        result
    }
}

/// Shared fallback for failures before a unit inventory can be constructed.
pub fn format_error(error: &anyhow::Error) -> String {
    Renderer::plain().render(&[
        Group::with_title(Level::ERROR.primary_title(format!("{error:#}"))),
        Group::with_title(Level::HELP.secondary_title("repair the reported source or citation, then run `cargo run -p mdbook-dada --bin dada-spec -- check`; see md/repo/correspondence-review.md")),
    ])
}

fn json_files(root: &Path, directory: &Path) -> Result<Vec<PathBuf>> {
    if !directory.exists() {
        return Ok(Vec::new());
    }
    ensure!(
        directory.canonicalize()?.starts_with(root),
        "evidence directory escapes project"
    );
    let mut files = Vec::new();
    for entry in fs::read_dir(directory)? {
        let path = entry?.path();
        ensure!(
            !fs::symlink_metadata(&path)?.file_type().is_symlink(),
            "evidence contains symbolic link {}",
            path.display()
        );
        if path
            .extension()
            .is_some_and(|extension| extension == "json")
        {
            files.push(path);
        }
    }
    files.sort();
    Ok(files)
}

/// Check all required units, including record presence, minimum inputs and freshness.
/// Neither the review's conclusion nor a passing result establishes a Lean proof.
pub fn check(inventory: &Inventory) -> Result<Report> {
    let mut report = Report::default();
    let mut bundles = BTreeMap::new();
    for path in json_files(&inventory.root, &inventory.root.join("evidence/bundles"))? {
        match read_json::<ReviewBundle>(&path) {
            Ok(bundle) => {
                let errors = bundle.integrity_errors();
                let name = path
                    .file_stem()
                    .and_then(|name| name.to_str())
                    .unwrap_or("");
                if !errors.is_empty() || name != bundle.digest {
                    report.issues.push(Issue {
                        unit: inventory
                            .units
                            .contains_key(&bundle.unit)
                            .then_some(bundle.unit.clone()),
                        message: format!("invalid evidence bundle {}", path.display()),
                        details: errors,
                    });
                } else {
                    bundles.insert(bundle.digest.clone(), bundle);
                }
            }
            Err(error) => report.issues.push(Issue {
                unit: None,
                message: "malformed evidence bundle".into(),
                details: vec![format!("{error:#}")],
            }),
        }
    }
    for id in &inventory.required {
        // Derive inputs even for pending obligations: malformed citations never
        // disappear merely because a proof or formalization is unfinished.
        if let Err(error) = inventory.inputs(id) {
            report.issues.push(Issue {
                unit: Some(id.clone()),
                message: "cannot resolve required evidence inputs".into(),
                details: vec![format!("{error:#}")],
            });
            report.statuses.push(UnitStatus {
                unit: id.clone(),
                evidence: "invalid sources",
                correspondence: "not checked",
                mechanical: "not recorded",
            });
            continue;
        }
        if !inventory.review_required(id)? {
            report.statuses.push(UnitStatus {
                unit: id.clone(),
                evidence: "pending obligation",
                correspondence: "not asserted",
                mechanical: "not recorded",
            });
            continue;
        }
        let mut current = BTreeSet::new();
        let mut stale = Vec::new();
        for bundle in bundles.values().filter(|bundle| &bundle.unit == id) {
            let errors = validate_bundle(inventory, bundle)?;
            if errors.is_empty() {
                current.insert(bundle.digest.clone());
            } else {
                stale.extend(errors);
            }
        }
        let mut records = BTreeMap::new();
        for path in json_files(
            &inventory.root,
            &inventory.root.join("evidence/records").join(id),
        )? {
            let parsed = (|| -> Result<ReviewRecord> {
                let review: ReviewRecord = read_json(&path)?;
                ensure!(
                    path.file_stem().and_then(|name| name.to_str()) == Some(&review.digest()?),
                    "record filename does not match contents"
                );
                let bundle = bundles
                    .get(&review.bundle)
                    .context("record's bundle is missing or malformed")?;
                ensure!(&bundle.unit == id, "record filed under wrong unit");
                let errors = validate_review(bundle, &review);
                ensure!(errors.is_empty(), "invalid review: {}", errors.join("; "));
                Ok(review)
            })();
            match parsed {
                Ok(review) => {
                    records.insert(review.digest()?, review);
                }
                Err(error) => report.issues.push(Issue {
                    unit: Some(id.clone()),
                    message: "malformed correspondence review".into(),
                    details: vec![format!("{error:#}")],
                }),
            }
        }
        let mut superseded = BTreeSet::new();
        for review in records.values() {
            for previous in &review.supersedes {
                if records.contains_key(previous) {
                    superseded.insert(previous.clone());
                } else {
                    report.issues.push(Issue {
                        unit: Some(id.clone()),
                        message: "review supersedes absent or unrelated evidence".into(),
                        details: vec![previous.clone()],
                    });
                }
            }
        }
        let stale_active = records.iter().any(|(digest, review)| {
            !superseded.contains(digest) && !current.contains(&review.bundle)
        });
        let active: Vec<_> = records
            .iter()
            .filter(|(digest, review)| {
                current.contains(&review.bundle) && !superseded.contains(*digest)
            })
            .map(|(_, review)| review)
            .collect();
        let evidence = if stale_active {
            "stale"
        } else if !current.is_empty() {
            "current"
        } else if !stale.is_empty() {
            "stale"
        } else {
            "missing"
        };
        let correspondence = if stale_active {
            "stale decision"
        } else if active.is_empty() {
            "missing"
        } else if active
            .iter()
            .any(|review| review.conclusion == Conclusion::Mismatch)
        {
            "mismatch"
        } else if active
            .iter()
            .any(|review| review.conclusion == Conclusion::Inconclusive)
        {
            "inconclusive"
        } else {
            "corresponds"
        };
        report.statuses.push(UnitStatus {
            unit: id.clone(),
            evidence,
            correspondence,
            mechanical: "not recorded",
        });
        if correspondence != "corresponds" {
            let mut details = if evidence == "stale" {
                stale
            } else {
                Vec::new()
            };
            details.sort();
            details.dedup();
            if evidence == "current" && active.is_empty() {
                details.push("preparing a bundle does not record a completed review".into());
            }
            report.issues.push(Issue {
                unit: Some(id.clone()),
                message: format!("{evidence} evidence for {id}: correspondence {correspondence}"),
                details,
            });
        }
    }
    Ok(report)
}

pub fn load_bundle(path: &Path) -> Result<ReviewBundle> {
    read_json(path)
}
pub fn load_review(path: &Path) -> Result<ReviewRecord> {
    read_json(path)
}

//! A small declarative diagram language, not a heap interpreter or invariant checker.
use crate::escape;
use anyhow::{bail, ensure, Context, Result};
use std::collections::{BTreeMap, BTreeSet};

#[derive(Debug)]
enum Kind {
    Variables,
    Object,
    Primitive,
    Array(usize),
}
#[derive(Debug)]
struct Node {
    id: String,
    label: String,
    kind: Kind,
    slots: Vec<(String, Option<(String, String)>)>,
}

fn identifier(s: &str) -> bool {
    let mut chars = s.chars();
    chars.next().is_some_and(|c| c.is_alphabetic() || c == '_')
        && chars.all(|c| c.is_alphanumeric() || c == '_')
}

fn args(s: &str) -> Result<Vec<String>> {
    let mut parts = vec![];
    let (mut quoted, mut escaped, mut start) = (false, false, 0);
    for (i, c) in s.char_indices() {
        if escaped {
            escaped = false;
            continue;
        }
        if quoted && c == '\\' {
            escaped = true;
            continue;
        }
        if c == '"' {
            quoted = !quoted;
        }
        if c == ',' && !quoted {
            parts.push(s[start..i].trim().to_owned());
            start = i + 1;
        }
    }
    ensure!(!quoted, "unterminated quoted argument");
    if !s.trim().is_empty() {
        parts.push(s[start..].trim().to_owned());
    }
    Ok(parts)
}
fn label(s: &str) -> Result<String> {
    if s.starts_with('"') {
        Ok(serde_json::from_str::<String>(s)?)
    } else {
        ensure!(
            !s.is_empty() && !s.contains(['(', ')', '"']),
            "invalid argument `{s}`"
        );
        Ok(s.to_owned())
    }
}

fn parse(source: &str) -> Result<Vec<Node>> {
    let mut nodes = Vec::<Node>::new();
    let mut assignments = vec![];
    for (line, text) in source.lines().enumerate() {
        let text = text.trim();
        if text.is_empty() || text.starts_with('#') {
            continue;
        }
        let result = (|| -> Result<()> {
            let (lhs, rhs) = text.split_once('=').context("expected an assignment")?;
            let lhs = lhs.trim();
            let (op, rest) = rhs
                .trim()
                .split_once('(')
                .context("expected constructor(arguments)")?;
            let op = op.trim();
            let arguments = args(
                rest.strip_suffix(')')
                    .context("expected closing parenthesis")?,
            )?;
            if lhs.contains('.') || lhs.contains('[') {
                assignments.push((lhs.to_owned(), op.to_owned(), arguments));
                return Ok(());
            }
            ensure!(identifier(lhs), "invalid node identifier `{lhs}`");
            ensure!(!nodes.iter().any(|n| n.id == lhs), "duplicate node `{lhs}`");
            let (kind, display) = match (op, arguments.as_slice()) {
                ("variables", []) => (Kind::Variables, "Variables".to_owned()),
                ("variables", [name]) => (Kind::Variables, label(name)?),
                ("object", [ty]) => (Kind::Object, format!("{} {lhs}", label(ty)?)),
                ("object", [ty, name]) => {
                    (Kind::Object, format!("{} {}", label(ty)?, label(name)?))
                }
                ("primitive", [value]) => (Kind::Primitive, format!("{lhs}: {}", label(value)?)),
                ("primitive", [value, name]) => (
                    Kind::Primitive,
                    format!("{}: {}", label(name)?, label(value)?),
                ),
                ("array", [length]) | ("array", [length, _]) => {
                    let length = length
                        .parse::<usize>()
                        .context("array length must be a nonnegative integer")?;
                    ensure!(length <= 64, "diagram arrays are limited to 64 slots");
                    let name = if arguments.len() == 2 {
                        label(&arguments[1])?
                    } else {
                        lhs.to_owned()
                    };
                    (Kind::Array(length), format!("{name} · length {length}"))
                }
                _ => bail!("unknown constructor or wrong arity: {op}"),
            };
            ensure!(
                !matches!(kind, Kind::Variables)
                    || !nodes
                        .iter()
                        .any(|node| matches!(node.kind, Kind::Variables)),
                "a heap diagram has at most one variable store"
            );
            let slots = if let Kind::Array(n) = kind {
                (0..n).map(|i| (format!("[{i}]"), None)).collect()
            } else {
                vec![]
            };
            nodes.push(Node {
                id: lhs.to_owned(),
                label: display,
                kind,
                slots,
            });
            Ok(())
        })();
        result.with_context(|| format!("heap facts line {}: {text}", line + 1))?;
    }
    ensure!(!nodes.is_empty(), "empty heap diagram");
    let mut seen = BTreeSet::new();
    for (lhs, op, args) in assignments {
        let (owner, slot, indexed) = if let Some((owner, index)) = lhs.split_once('[') {
            let index = index
                .strip_suffix(']')
                .context("expected closing array index")?
                .parse::<usize>()?;
            (owner, format!("[{index}]"), Some(index))
        } else {
            let (owner, slot) = lhs.split_once('.').context("expected node.slot")?;
            ensure!(identifier(slot), "invalid slot name `{slot}`");
            (owner, slot.to_owned(), None)
        };
        ensure!(
            seen.insert((owner.to_owned(), slot.clone())),
            "duplicate slot `{lhs}`"
        );
        let value = match (op.as_str(), args.as_slice()) {
            ("uninitialized", []) => None,
            ("lease" | "leased", [target]) => Some(("leased".to_owned(), target.clone())),
            ("owned" | "showned" | "shlease" | "shared", [target]) => {
                let target_node = nodes
                    .iter()
                    .find(|n| n.id == *target)
                    .with_context(|| format!("unknown target `{target}`"))?;
                ensure!(
                    !matches!(target_node.kind, Kind::Variables),
                    "reference cannot target variable store `{target}`"
                );
                // `shared` is a diagram shorthand for a shared lease. Ownership is
                // always spelled `showned`, never inferred from the other edges.
                Some((
                    if op == "shared" {
                        "shlease".to_owned()
                    } else {
                        op
                    },
                    target.clone(),
                ))
            }
            _ => bail!("unknown reference constructor or wrong arity in `{lhs}`"),
        };
        let node = nodes
            .iter_mut()
            .find(|n| n.id == owner)
            .with_context(|| format!("unknown slot owner `{owner}`"))?;
        match (&node.kind, indexed) {
            (Kind::Array(length), Some(index)) => {
                ensure!(index < *length, "array index out of bounds in `{lhs}`");
                node.slots[index].1 = value;
            }
            (Kind::Variables | Kind::Object, None) => node.slots.push((slot, value)),
            _ => bail!("invalid slot projection in `{lhs}`"),
        }
    }
    for node in &nodes {
        for (_, value) in &node.slots {
            if let Some((kind, target)) = value {
                if kind == "leased" {
                    let (n, slot) = edge_target(&nodes, target)?;
                    let edge = nodes[n].slots[slot]
                        .1
                        .as_ref()
                        .context("lease target is uninitialized")?;
                    ensure!(
                        matches!(edge.0.as_str(), "owned" | "leased"),
                        "lease target must be an owned or leased edge: {target}"
                    );
                }
            }
        }
    }
    Ok(nodes)
}

fn edge_target(nodes: &[Node], target: &str) -> Result<(usize, usize)> {
    let (owner, slot) = if let Some((owner, slot)) = target.split_once('.') {
        (owner, slot.to_owned())
    } else if let Some((owner, index)) = target.split_once('[') {
        let index = index
            .strip_suffix(']')
            .context("expected array edge index")?
            .parse::<usize>()?;
        (owner, format!("[{index}]"))
    } else {
        bail!("lease target must name an edge, such as α.f or vars.p: {target}");
    };
    let n = nodes
        .iter()
        .position(|n| n.id == owner)
        .with_context(|| format!("unknown edge owner `{owner}`"))?;
    let s = nodes[n]
        .slots
        .iter()
        .position(|(name, _)| *name == slot)
        .with_context(|| format!("unknown edge `{target}`"))?;
    Ok((n, s))
}

pub fn render(source: &str) -> Result<String> {
    let nodes = parse(source)?;
    let lookup: BTreeMap<_, _> = nodes
        .iter()
        .enumerate()
        .map(|(i, n)| (n.id.as_str(), i))
        .collect();
    // Assign depth by first-discovered owning root path. Cycles and disconnected objects remain
    // renderable; the diagram language does not claim ownership well-formedness.
    let mut depths = vec![None; nodes.len()];
    for (i, n) in nodes.iter().enumerate() {
        if matches!(n.kind, Kind::Variables) {
            depths[i] = Some(0);
        }
    }
    for _ in 0..nodes.len() {
        let mut changed = false;
        for (i, n) in nodes.iter().enumerate() {
            if let Some(depth) = depths[i] {
                for (_, value) in &n.slots {
                    if let Some((kind, target)) = value {
                        if !matches!(kind.as_str(), "owned" | "showned") {
                            continue;
                        }
                        let j = lookup[target.as_str()];
                        if depths[j].is_none() {
                            depths[j] = Some(depth + 1);
                            changed = true;
                        }
                    }
                }
            }
        }
        if !changed {
            break;
        }
    }
    let width = nodes
        .iter()
        .map(|n| n.label.chars().count())
        .max()
        .unwrap_or(0)
        .max(18) as f64
        * 8.0
        + 32.0;
    let stride = width + 150.0;
    let mut bottoms = BTreeMap::<usize, f64>::new();
    let positions: Vec<_> = nodes
        .iter()
        .enumerate()
        .map(|(i, n)| {
            let depth = depths[i].unwrap_or(1);
            let y = *bottoms.entry(depth).or_insert(30.0);
            let height = 48.0 + 32.0 * n.slots.len() as f64;
            bottoms.insert(depth, y + height + 65.0);
            (30.0 + depth as f64 * stride, y, height)
        })
        .collect();
    let canvas_width = positions
        .iter()
        .map(|(x, _, _)| x + width + 90.0)
        .fold(0.0, f64::max);
    let canvas_height = bottoms.values().copied().fold(0.0, f64::max);
    let mut svg=format!("<svg xmlns=\"http://www.w3.org/2000/svg\" class=\"heap-diagram\" role=\"img\" aria-label=\"Heap objects and references\" style=\"max-width:{canvas_width}px\" viewBox=\"0 0 {canvas_width} {canvas_height}\"><title>Heap objects and references</title><desc>{}</desc>",escape(source));
    for (i, n) in nodes.iter().enumerate() {
        let (x, y, height) = positions[i];
        let class = if matches!(n.kind, Kind::Variables) {
            "heap-variables"
        } else {
            "heap-object"
        };
        svg.push_str(&format!("<g class=\"{class}\"><rect x=\"{x}\" y=\"{y}\" width=\"{width}\" height=\"{height}\" rx=\"6\"/><text x=\"{}\" y=\"{}\" class=\"heap-title\">{}</text>",x+12.0,y+27.0,escape(&n.label)));
        for (s, (slot, value)) in n.slots.iter().enumerate() {
            let sy = y + 62.0 + s as f64 * 32.0;
            let contents = if value.is_none() {
                format!("{slot}: uninitialized")
            } else {
                slot.clone()
            };
            svg.push_str(&format!(
                "<text x=\"{}\" y=\"{sy}\">{}</text>",
                x + 12.0,
                escape(&contents)
            ));
        }
        svg.push_str("</g>");
    }
    for (i, n) in nodes.iter().enumerate() {
        let (x, y, _) = positions[i];
        for (s, (_, value)) in n.slots.iter().enumerate() {
            if let Some((kind, target)) = value {
                let sy = y + 57.0 + s as f64 * 32.0;
                let (tx, ey, edge_targeted) = if kind == "leased" {
                    let (n, slot) = edge_target(&nodes, target)?;
                    let (x, y, _) = positions[n];
                    (x + width + 12.0, y + 57.0 + slot as f64 * 32.0, true)
                } else {
                    let (x, y, height) = positions[lookup[target.as_str()]];
                    (x, sy.clamp(y + 12.0, y + height - 12.0), false)
                };
                let sx = x + width;
                let boxes: Vec<_> = positions
                    .iter()
                    .map(|&(x, y, h)| (x as i64, y as i64, width as i64, h as i64))
                    .collect();
                let route = crate::routing::route(
                    ((sx + 35.0) as i64, sy as i64),
                    (
                        (if edge_targeted { tx } else { tx - 20.0 }) as i64,
                        ey as i64,
                    ),
                    &boxes,
                )?;
                let mut d = format!("M {sx} {sy} H {}", sx + 35.0);
                for &(px, py) in route.iter().skip(1) {
                    d.push_str(&format!(" L {px} {py}"));
                }
                if !edge_targeted {
                    d.push_str(&format!(" L {tx} {ey}"));
                }
                let dot_class = if edge_targeted {
                    "heap-junction"
                } else {
                    "heap-endpoint"
                };
                svg.push_str(&format!("<g class=\"heap-edge {kind}\"><path d=\"{d}\"/><circle class=\"{dot_class}\" cx=\"{tx}\" cy=\"{ey}\" r=\"3\" fill=\"currentColor\"/><text x=\"{}\" y=\"{}\">{kind}</text></g>",sx+5.0,sy-7.0));
            }
        }
    }
    svg.push_str("</svg>");
    Ok(svg)
}

#[cfg(test)]
mod tests {
    use super::*;
    #[test]
    fn facts_render_unicode_fields_and_reference_kinds() {
        let facts="vars = variables()\nα = object(Point, \"α\")\nβ = primitive(22)\nvars.p = owned(α)\nvars.q = shared(α)\nα.x = owned(β)";
        let svg = render(facts).unwrap();
        assert!(svg.contains("Point α"));
        assert!(svg.contains("heap-edge shlease"));
        assert_eq!(svg.matches("<g class=\"heap-edge").count(), 3);
        assert_eq!(svg, render(facts).unwrap());
    }
    #[test]
    fn arrays_materialize_uninitialized_slots_and_validate_indices() {
        let nodes = parse("a = array(2)\np = primitive(9)\na[0] = owned(p)").unwrap();
        assert_eq!(nodes[0].slots.len(), 2);
        assert!(nodes[0].slots[1].1.is_none());
        assert!(render("a = array(2)\na[2] = uninitialized()").is_err());
    }
    #[test]
    fn bad_facts_fail_instead_of_silently_changing_the_graph() {
        for facts in [
            "a = variables()\na = variables()",
            "a = variables()\nb = variables()",
            "a = frame()",
            "a = variables()\na.p = owned(missing)",
            "a = variables()\na.p = owned(a)",
            "a = primitive(1)\na.x = uninitialized()",
            "a = variables()\na.p = uninitialized()\na.p = uninitialized()",
            "a = unknown()",
        ] {
            assert!(render(facts).is_err(), "{facts}");
        }
    }
    #[test]
    fn variable_store_groups_slots_without_becoming_a_reference_target() {
        let facts = "vars = variables()\na = primitive(1)\nvars.x = owned(a)\nvars.y = lease(vars.x)\nvars.z = uninitialized()";
        let nodes = parse(facts).unwrap();
        assert_eq!(nodes[0].label, "Variables");
        assert_eq!(nodes[0].slots.len(), 3);
        let svg = render(facts).unwrap();
        assert!(svg.contains("class=\"heap-variables\""));
        assert!(svg.contains("class=\"heap-junction\""));
        assert!(render(&format!("{facts}\nvars.bad = owned(vars)")).is_err());
        assert!(render("vars = variables(\"Live variables\")")
            .unwrap()
            .contains("Live variables"));
    }
    #[test]
    fn labels_are_escaped_and_quoted_commas_are_preserved() {
        let svg = render("a = object(Point, \"<script>, &\\\"\")").unwrap();
        assert!(!svg.contains("<script>"));
        assert!(svg.contains("&lt;script&gt;, &amp;&quot;"));
    }
}

#[cfg(test)]
mod lease_tests {
    use super::*;

    #[test]
    fn leases_join_edges_and_shleases_target_objects() {
        let facts = "vars = variables()\nα = object(C)\nβ = primitive(1)\nvars.p = owned(α)\nα.f = owned(β)\nvars.q = lease(α.f)\nvars.r = lease(vars.q)\nvars.s = shlease(β)";
        let svg = render(facts).unwrap();
        assert_eq!(svg.matches("class=\"heap-junction\"").count(), 2);
        assert!(svg.contains("heap-edge shlease"));
        for target in ["β", "α.missing", "vars.s", "α.empty"] {
            let bad = format!("{facts}\nα.empty = uninitialized()\nvars.bad = lease({target})");
            assert!(render(&bad).is_err(), "{target}");
        }
        assert!(render(
            "vars = variables()\na = array(1)\nb = primitive(2)\nvars.q = lease(a[0])\na[0] = owned(b)"
        )
        .is_ok());
        assert!(render(
            "vars = variables()\na = primitive(1)\nvars.p = owned(a)\nvars.q = shlease(vars.p)"
        )
        .is_err());
    }
}

#[cfg(test)]
mod cycle_tests {
    use super::*;

    #[test]
    fn cycles_self_loops_and_disconnected_cycles_render_deterministically() {
        let rect = regex::Regex::new(
            r#"<rect x="([\d.]+)" y="([\d.]+)" width="([\d.]+)" height="([\d.]+)""#,
        )
        .unwrap();
        let paths = regex::Regex::new(r#"<path d="([^"]+)""#).unwrap();
        for facts in [
            "a = object(Node)\na.next = showned(a)",
            "a = object(Node)\nb = object(Node)\na.next = showned(b)\nb.next = showned(a)",
            "vars = variables()\na = object(Node)\nb = object(Node)\nvars.p = showned(a)\na.next = showned(b)\nb.next = showned(a)",
        ] {
            let svg = render(facts).unwrap();
            assert_eq!(svg, render(facts).unwrap());
            assert!(!svg.contains("NaN"));
            assert!(!svg.contains("heap-arrow"));
            let nodes = parse(facts).unwrap();
            let count = nodes.iter().flat_map(|n| &n.slots).filter(|(_, v)| v.is_some()).count();
            assert_eq!(svg.matches("class=\"heap-endpoint\"").count(), count);
            // Check every routed segment against every rendered rectangle, including
            // the source and destination: only boundary contact is permitted.
            let boxes: Vec<Vec<f64>> = rect.captures_iter(&svg).map(|c| (1..=4).map(|i| c[i].parse().unwrap()).collect()).collect();
            for c in paths.captures_iter(&svg) {
                let mut tokens = c[1].split_whitespace();
                let mut last = (0.0_f64, 0.0_f64);
                while let Some(op) = tokens.next() {
                    let x: f64 = tokens.next().unwrap().parse().unwrap();
                    let next = if op == "H" { (x,last.1) } else { (x,tokens.next().unwrap().parse().unwrap()) };
                    if op != "M" {
                        assert!(last.0 == next.0 || last.1 == next.1);
                        for b in &boxes {
                            let crosses = if last.0 == next.0 {
                                last.0 > b[0] && last.0 < b[0]+b[2] && last.1.min(next.1) < b[1]+b[3] && last.1.max(next.1) > b[1]
                            } else {
                                last.1 > b[1] && last.1 < b[1]+b[3] && last.0.min(next.0) < b[0]+b[2] && last.0.max(next.0) > b[0]
                            };
                            assert!(!crosses, "edge crosses box in {facts}");
                        }
                    }
                    last = next;
                }
            }
        }
    }
}

//! The current, independently derived specification inventory and review inputs.
use crate::{
    lean, rust_source,
    units::{self, SpecUnit, UnitKind},
};
use anyhow::{bail, ensure, Context, Result};
use serde::{Deserialize, Serialize};
use sha2::{Digest, Sha256};
use std::{
    collections::{BTreeMap, BTreeSet},
    fs,
    path::{Component, Path, PathBuf},
};

pub const SCHEMA: u32 = 1;

#[derive(Debug, Deserialize, Serialize)]
#[serde(deny_unknown_fields)]
pub struct Config {
    pub schema: u32,
    pub chapters: Vec<String>,
    pub policies: Vec<String>,
    #[serde(default)]
    pub context: Vec<String>,
}

#[derive(Clone, Debug, Serialize, Deserialize, PartialEq, Eq)]
#[serde(deny_unknown_fields)]
pub struct Input {
    pub key: String,
    pub path: String,
    pub line: usize,
    pub content: String,
    pub sha256: String,
}

impl Input {
    pub fn new(key: String, path: String, line: usize, content: String) -> Self {
        let sha256 = hash(content.as_bytes());
        Self {
            key,
            path,
            line,
            content,
            sha256,
        }
    }

    /// Context snapshots are available to reviewers, without asserting that every
    /// unrelated declaration or proof in a conservatively captured file was read.
    pub fn requires_examination(&self) -> bool {
        ["unit:", "lean:", "rust:", "test:", "policy:", "extra:"]
            .iter()
            .any(|prefix| self.key.starts_with(prefix))
    }
}

pub fn hash(bytes: &[u8]) -> String {
    Sha256::digest(bytes)
        .iter()
        .map(|byte| format!("{byte:02x}"))
        .collect()
}

/// Existing input paths must be relative, canonical, and contained in the project.
/// Evidence output may never become its own input.
pub fn input_path(root: &Path, relative: &str) -> Result<PathBuf> {
    let path = Path::new(relative);
    ensure!(
        !path.as_os_str().is_empty()
            && path
                .components()
                .all(|part| matches!(part, Component::Normal(_))),
        "input path must be a normal relative path: {relative}"
    );
    ensure!(
        !path.starts_with("evidence") && !path.starts_with("target") && !path.starts_with("book"),
        "generated output cannot be a review input: {relative}"
    );
    let canonical = root
        .join(path)
        .canonicalize()
        .with_context(|| format!("resolving input {relative}"))?;
    ensure!(
        canonical.starts_with(root),
        "input escapes project: {relative}"
    );
    let resolved = canonical.strip_prefix(root)?;
    ensure!(
        !resolved.starts_with("evidence")
            && !resolved.starts_with("target")
            && !resolved.starts_with("book"),
        "generated output cannot be a review input: {relative}"
    );
    Ok(canonical)
}

pub fn relative_path(root: &Path, path: &Path) -> Result<String> {
    Ok(path
        .strip_prefix(root)
        .context("source is outside the project")?
        .to_str()
        .context("source path is not UTF-8")?
        .replace('\\', "/"))
}

fn files(root: &Path, directory: &Path, extension: &str) -> Result<Vec<PathBuf>> {
    let mut result = Vec::new();
    for entry in
        fs::read_dir(directory).with_context(|| format!("reading {}", directory.display()))?
    {
        let entry = entry?;
        let path = entry.path();
        if entry.file_name().to_string_lossy().starts_with('.') {
            continue;
        }
        ensure!(
            !entry.file_type()?.is_symlink(),
            "source directory contains a symbolic link: {}",
            path.display()
        );
        ensure!(path.starts_with(root), "source path escapes project");
        if path.is_dir() {
            result.extend(files(root, &path, extension)?);
        } else if path.extension().is_some_and(|ext| ext == extension) {
            result.push(path);
        }
    }
    result.sort();
    Ok(result)
}

pub struct Inventory {
    pub root: PathBuf,
    pub config: Config,
    pub units: BTreeMap<String, SpecUnit>,
    pub required: BTreeSet<String>,
    pub sources: BTreeMap<String, String>,
}

impl Inventory {
    pub fn load(root: &Path) -> Result<Self> {
        let root = root
            .canonicalize()
            .context("resolving specification root")?;
        let config: Config = serde_json::from_str(
            &fs::read_to_string(root.join("spec.json")).context("reading spec.json")?,
        )
        .context("parsing spec.json")?;
        ensure!(
            config.schema == SCHEMA,
            "unsupported specification schema {}",
            config.schema
        );
        ensure!(
            !config.chapters.is_empty(),
            "spec.json must name at least one strict chapter"
        );
        ensure!(
            !config.policies.is_empty(),
            "spec.json must name a review policy"
        );
        let mut units = BTreeMap::new();
        let mut sources = BTreeMap::new();
        for path in files(&root, &root.join("md"), "md")? {
            let name = relative_path(&root, &path)?;
            let source = fs::read_to_string(&path)?;
            for unit in units::parse(&source, &name)? {
                ensure!(
                    !units.contains_key(&unit.id),
                    "duplicate unit ID {}",
                    unit.id
                );
                units.insert(unit.id.clone(), unit);
            }
            sources.insert(name, source);
        }
        let mut required = BTreeSet::new();
        let mut chapters = BTreeSet::new();
        for chapter in &config.chapters {
            input_path(&root, chapter)?;
            ensure!(
                chapters.insert(chapter),
                "duplicate strict chapter {chapter}"
            );
            let source = sources
                .get(chapter)
                .with_context(|| format!("strict chapter is not Markdown under md/: {chapter}"))?;
            units::validate_coverage(source, chapter)?;
            let ids: Vec<_> = units
                .values()
                .filter(|unit| &unit.source_path == chapter)
                .map(|unit| unit.id.clone())
                .collect();
            ensure!(!ids.is_empty(), "strict chapter has no units: {chapter}");
            required.extend(ids);
        }
        // A new-style unit always participates, even before its chapter becomes
        // strict about free-floating prose. Legacy directives are not units.
        required.extend(units.keys().cloned());
        for unit in units.values() {
            for dependency in unit
                .uses
                .iter()
                .chain(units::required_linked_ids(&unit.body)?.iter())
            {
                ensure!(
                    units.contains_key(dependency),
                    "{}: {} uses missing unit {dependency}",
                    unit.source_path,
                    unit.id
                );
            }
        }
        for path in config.policies.iter().chain(&config.context) {
            input_path(&root, path)?;
        }
        Ok(Self {
            root,
            config,
            units,
            required,
            sources,
        })
    }

    fn file_input(&self, key: String, name: &str) -> Result<Input> {
        let path = input_path(&self.root, name)?;
        Ok(Input::new(
            key,
            name.to_owned(),
            1,
            fs::read_to_string(&path).with_context(|| format!("reading input {name}"))?,
        ))
    }

    fn add_unit(
        &self,
        id: &str,
        inputs: &mut BTreeMap<String, Input>,
        visited: &mut BTreeSet<String>,
    ) -> Result<()> {
        if !visited.insert(id.to_owned()) {
            return Ok(());
        }
        let unit = self
            .units
            .get(id)
            .with_context(|| format!("unknown unit {id}"))?;
        let source = &self.sources[&unit.source_path];
        let line = source[..unit.range.start]
            .bytes()
            .filter(|b| *b == b'\n')
            .count()
            + 1;
        let input = Input::new(
            format!("unit:{id}"),
            unit.source_path.clone(),
            line,
            unit.raw.clone(),
        );
        inputs.insert(input.key.clone(), input);
        for target in &unit.lean {
            let selected = lean::select(&self.root.join("lean"), target, unit.kind)
                .with_context(|| format!("{}: {id} citation {target}", unit.source_path))?;
            let path = relative_path(&self.root, &selected.path)?;
            let offset = selected.source.find(&selected.selected).unwrap_or(0);
            let line = selected.source[..offset]
                .bytes()
                .filter(|b| *b == b'\n')
                .count()
                + 1;
            let input = Input::new(format!("lean:{target}"), path, line, selected.selected);
            inputs.insert(input.key.clone(), input);
        }
        for (prefix, targets) in [("rust", &unit.rust), ("test", &unit.tests)] {
            for target in targets {
                let selected = rust_source::select(&self.root, target)
                    .with_context(|| format!("{}: {id} citation {target}", unit.source_path))?;
                if prefix == "test" {
                    ensure!(
                        selected.is_test,
                        ":tests: target must be a #[test] function: {target}"
                    );
                }
                let path = relative_path(&self.root, &selected.path)?;
                let offset = selected.source.find(&selected.selected).unwrap_or(0);
                let line = selected.source[..offset]
                    .bytes()
                    .filter(|b| *b == b'\n')
                    .count()
                    + 1;
                let input = Input::new(
                    format!("{prefix}:{target}"),
                    path.clone(),
                    line,
                    selected.selected,
                );
                inputs.insert(input.key.clone(), input);
                let context = self.file_input(format!("context:{path}"), &path)?;
                inputs.insert(context.key.clone(), context);
            }
        }
        let linked = units::linked_ids(&unit.body)?;
        for dependency in unit
            .uses
            .iter()
            .chain(linked.iter().filter(|id| self.units.contains_key(*id)))
        {
            self.add_unit(dependency, inputs, visited)?;
        }
        Ok(())
    }

    /// Derive required snapshots from current sources, never from a review record.
    pub fn inputs(&self, id: &str) -> Result<Vec<Input>> {
        let mut inputs = BTreeMap::new();
        self.add_unit(id, &mut inputs, &mut BTreeSet::new())?;
        for path in [
            "spec.json",
            "Cargo.toml",
            "Cargo.lock",
            "mdbook-dada/Cargo.toml",
        ] {
            let input = self.file_input(format!("tool:{path}"), path)?;
            inputs.insert(input.key.clone(), input);
        }
        for directory in ["mdbook-dada/src", "mdbook-dada/tests"] {
            for path in files(&self.root, &self.root.join(directory), "rs")? {
                let name = relative_path(&self.root, &path)?;
                let input = self.file_input(format!("tool:{name}"), &name)?;
                inputs.insert(input.key.clone(), input);
            }
        }
        for (prefix, paths) in [
            ("policy", &self.config.policies),
            ("context", &self.config.context),
        ] {
            for path in paths {
                let input = self.file_input(format!("{prefix}:{path}"), path)?;
                inputs.insert(input.key.clone(), input);
            }
        }
        if inputs.keys().any(|key| key.starts_with("lean:")) {
            for path in files(&self.root, &self.root.join("lean"), "lean")? {
                let name = relative_path(&self.root, &path)?;
                let input = self.file_input(format!("context:{name}"), &name)?;
                inputs.insert(input.key.clone(), input);
            }
            for path in [
                "lean/lean-toolchain",
                "lean/lakefile.toml",
                "lean/lake-manifest.json",
            ] {
                let input = self.file_input(format!("context:{path}"), path)?;
                inputs.insert(input.key.clone(), input);
            }
        }
        Ok(inputs.into_values().collect())
    }

    pub fn extra_input(&self, path: &str) -> Result<Input> {
        self.file_input(format!("extra:{path}"), path)
    }

    pub fn unit(&self, id: &str) -> Result<&SpecUnit> {
        self.units
            .get(id)
            .with_context(|| format!("unknown unit {id}"))
    }

    pub fn review_required(&self, id: &str) -> Result<bool> {
        Ok(self.unit(id)?.kind != UnitKind::Obligation)
    }
}

pub fn find_root(start: &Path) -> Result<PathBuf> {
    for parent in start.ancestors() {
        for candidate in [parent.to_path_buf(), parent.join("v2")] {
            if candidate.join("spec.json").is_file() {
                return Ok(candidate);
            }
        }
    }
    bail!("cannot find spec.json; run from the repository or v2 directory")
}

//! Extraction of a deliberately restricted, line-oriented Lean declaration style.
use anyhow::{ensure, Context, Result};
use std::collections::HashSet;
use std::path::{Component, Path};

// Mask comments and strings while retaining byte offsets and newlines.
fn mask(source: &str) -> Result<String> {
    Ok(scan(source)?.code)
}

// Retain the offsets of real line comments so source anchors cannot be forged
// by text inside strings or nested block comments.
fn mask_and_comments(source: &str) -> Result<(String, Vec<usize>)> {
    let scanned = scan(source)?;
    Ok((scanned.code, scanned.line_comments))
}

struct Scanned {
    code: String,
    line_comments: Vec<usize>,
    // End of the final code token, literal, or attached inline comment. Unlike
    // `code.trim_end()`, this retains a body ending in a string literal.
    content_end: usize,
}

fn scan(source: &str) -> Result<Scanned> {
    let bytes = source.as_bytes();
    let mut output = bytes.to_vec();
    let mut comments = Vec::new();
    let mut content_end = 0;
    let mut i = 0;
    while i < bytes.len() {
        let start = i;
        let mut comment = false;
        if bytes.get(i..i + 2) == Some(b"/-") {
            comment = true;
            i += 2;
            let mut depth = 1;
            while i < bytes.len() && depth > 0 {
                match bytes.get(i..i + 2) {
                    Some(b"/-") => {
                        depth += 1;
                        i += 2;
                    }
                    Some(b"-/") => {
                        depth -= 1;
                        i += 2;
                    }
                    _ => i += 1,
                }
            }
            ensure!(depth == 0, "unterminated Lean comment");
        } else if bytes.get(i..i + 2) == Some(b"--") {
            comment = true;
            comments.push(i);
            i = source[i..].find('\n').map_or(bytes.len(), |n| i + n);
        } else if let Some((quote, hashes)) = raw_string_start(source, i) {
            let closing = format!("\"{}", "#".repeat(hashes));
            let tail = quote + 1;
            i = tail
                + source[tail..]
                    .find(&closing)
                    .context("unterminated Lean raw string")?
                + closing.len();
        } else if let Some(end) = character_end(source, i) {
            i = end;
        } else if source[i..].starts_with('«') {
            i += source[i..]
                .find('»')
                .context("unterminated Lean quoted identifier")?
                + '»'.len_utf8();
        } else if bytes[i] == b'"' {
            i += 1;
            loop {
                ensure!(i < bytes.len(), "unterminated Lean string");
                match bytes[i] {
                    b'"' => {
                        i += 1;
                        break;
                    }
                    b'\\' => i += 2,
                    _ => i += 1,
                }
            }
        } else {
            // Keep UTF-8 boundaries for the character-literal lookahead below.
            let c = source[i..].chars().next().unwrap();
            i += c.len_utf8();
            if !c.is_whitespace() {
                content_end = i;
            }
            continue;
        }
        if !comment || !source[content_end..start].contains('\n') {
            // Keep comments beginning on the final code line, including a
            // block comment continuing onto later lines. Standalone comments
            // after the body belong to neither the selected declaration nor
            // its source extent. Comments before later code remain intact.
            content_end = i;
        }
        for byte in &mut output[start..i] {
            if *byte != b'\n' {
                *byte = b' ';
            }
        }
    }
    Ok(Scanned {
        code: String::from_utf8(output)?,
        line_comments: comments,
        content_end,
    })
}

fn follows_identifier(source: &str, offset: usize) -> bool {
    source[..offset]
        .chars()
        .next_back()
        .is_some_and(|c| c.is_alphanumeric() || matches!(c, '_' | '\''))
}

// Lean raw strings use r"...", r#"..."#, r##"..."##, etc. Their
// contents have neither escapes nor comments, including any embedded quotes.
fn raw_string_start(source: &str, start: usize) -> Option<(usize, usize)> {
    let bytes = source.as_bytes();
    if bytes[start] != b'r' || follows_identifier(source, start) {
        return None;
    }
    let mut quote = start + 1;
    while bytes.get(quote) == Some(&b'#') {
        quote += 1;
    }
    (bytes.get(quote) == Some(&b'"')).then_some((quote, quote - start - 1))
}

fn character_end(source: &str, start: usize) -> Option<usize> {
    let bytes = source.as_bytes();
    if bytes[start] != b'\'' || follows_identifier(source, start) {
        return None;
    }
    let mut end = start + 1;
    let character = source[end..].chars().next()?;
    end += character.len_utf8();
    if character == '\\' {
        end += match bytes.get(end)? {
            b'x' => 3,
            b'u' => 5,
            _ => 1,
        };
    }
    (bytes.get(end) == Some(&b'\'')).then_some(end + 1)
}

pub fn extract(source: &str, name: &str) -> Result<String> {
    extract_declaration(source, name, Selection::Type)
}

fn extract_theorem(source: &str, name: &str) -> Result<String> {
    extract_declaration(source, name, Selection::Theorem)
}

fn extract_definition(source: &str, name: &str) -> Result<String> {
    extract_declaration(source, name, Selection::Definition)
}

#[derive(Clone, Copy, PartialEq, Eq)]
enum Selection {
    Type,
    Theorem,
    Definition,
}

fn extract_declaration(source: &str, name: &str, selection: Selection) -> Result<String> {
    let simple_name = |component: &str| {
        !component.is_empty() && component.chars().all(|c| c.is_alphanumeric() || c == '_')
    };
    if selection != Selection::Type {
        ensure!(
            name.split('.').all(simple_name),
            "use a declaration name with nonempty identifier components separated by single dots"
        );
    } else {
        ensure!(
            simple_name(name),
            "use a simple unqualified declaration name"
        );
    }
    let masked = mask(source)?;
    ensure!(
        !masked.lines().any(|l| l.trim() == "mutual"),
        "mutual declarations are unsupported"
    );
    let mut found = Vec::new();
    let mut offset = 0;
    let lines: Vec<_> = masked
        .split_inclusive('\n')
        .map(|line| {
            let start = offset;
            offset += line.len();
            (start, line)
        })
        .collect();
    let structure_field = regex::Regex::new(r"^[ \t]+[A-Za-z_][A-Za-z0-9_']*[ \t]*:(?:[^:=]|$)")?;
    for (i, &(start, line)) in lines.iter().enumerate() {
        let words: Vec<_> = line.split_whitespace().collect();
        if selection == Selection::Definition {
            let declaration: Vec<_> = words
                .iter()
                .copied()
                .skip_while(|word| {
                    matches!(
                        *word,
                        "private" | "protected" | "noncomputable" | "unsafe" | "partial" | "nonrec"
                    )
                })
                .collect();
            // Literal names are intentionally not resolved through namespaces.
            // A same-named declaration of the wrong kind must not disappear
            // from an otherwise ambiguous citation.
            if declaration.get(1) == Some(&name)
                && matches!(
                    declaration.first(),
                    Some(
                        &"def"
                            | &"abbrev"
                            | &"structure"
                            | &"inductive"
                            | &"theorem"
                            | &"lemma"
                            | &"axiom"
                            | &"opaque"
                            | &"constant"
                            | &"class"
                    )
                )
            {
                ensure!(
                    declaration.len() == words.len(),
                    "declaration modifiers are unsupported"
                );
                ensure!(
                    matches!(declaration.first(), Some(&"def" | &"abbrev" | &"structure" | &"inductive")),
                    "definition citations must select def, abbrev, structure, or inductive declarations"
                );
            }
        }
        if words.get(1) != Some(&name) {
            continue;
        }
        let supported = match selection {
            Selection::Theorem => words.first() == Some(&"theorem"),
            Selection::Type => {
                matches!(words.first(), Some(&"inductive" | &"structure" | &"abbrev"))
            }
            Selection::Definition => matches!(
                words.first(),
                Some(&"def" | &"inductive" | &"structure" | &"abbrev")
            ),
        };
        if !supported {
            continue;
        }
        ensure!(
            !line.starts_with(char::is_whitespace),
            "selected Lean declarations must begin at column zero"
        );
        if let Some((_, previous)) = lines[..i].iter().rev().find(|(_, l)| !l.trim().is_empty()) {
            ensure!(
                !previous.trim_start().starts_with("@["),
                "declaration attributes are unsupported"
            );
        }
        if let Some((_, boundary)) = lines[i + 1..]
            .iter()
            .find(|(_, l)| !l.trim().is_empty() && !l.starts_with(char::is_whitespace))
        {
            let mut words = boundary.split_whitespace();
            let first = words.next().unwrap_or("");
            let mut word = first;
            while matches!(
                word,
                "private" | "protected" | "noncomputable" | "unsafe" | "partial" | "nonrec"
            ) {
                word = words.next().unwrap_or("");
            }
            ensure!(
                (word == first
                    || matches!(
                        word,
                        "inductive" | "structure" | "abbrev" | "def" | "theorem" | "instance"
                    ))
                    && matches!(
                        word,
                        "inductive"
                            | "structure"
                            | "abbrev"
                            | "def"
                            | "theorem"
                            | "lemma"
                            | "example"
                            | "instance"
                            | "end"
                            | "namespace"
                            | "section"
                            | "variable"
                            | "open"
                            | "#check"
                    ),
                "unsupported declaration boundary `{}`; continuation lines must be indented",
                boundary.trim()
            );
        }
        let end = lines[i + 1..]
            .iter()
            .find(|(_, l)| !l.trim().is_empty() && !l.starts_with(char::is_whitespace))
            .map(|(n, _)| *n)
            .unwrap_or(source.len());
        let body = &source[start..end];
        let text = &body[..scan(body)?.content_end];
        if selection != Selection::Type {
            let code = &masked[start..end];
            // A structure field such as `variables : Store` is not a command.
            // Only exempt a bare, indented field name followed by a type colon;
            // `variable (x : Nat)` and `def sibling := ...` remain commands.
            let commands = command_pattern()?
                .find_iter(code)
                .filter(|command| {
                    words[0] != "structure"
                        || !structure_field
                            .is_match(code[command.start()..].lines().next().unwrap_or(""))
                })
                .count();
            ensure!(
                commands == 1,
                "selected declaration must contain no other commands, even when indented"
            );
        }
        if selection == Selection::Theorem {
            ensure!(
                has_definition_body(&masked[start..end]),
                "theorem must include its proof body (`:=`)"
            );
        } else if selection == Selection::Definition && words[0] == "def" {
            ensure!(
                has_named_definition_body(&masked[start..end])?,
                "definition must include a body (`:=`, `where`, or indented equations with `=>`)"
            );
        } else if words[0] != "abbrev" {
            ensure!(
                line.contains("where"),
                "declaration header must contain `where` on its first line"
            );
        } else {
            if selection == Selection::Definition {
                ensure!(
                    has_definition_body(&masked[start..end]),
                    "abbreviation must include a body (`:=`)"
                );
            } else {
                ensure!(line.contains(":="), "abbreviation header must contain `:=`");
            }
        }
        found.push(text.to_owned());
    }
    ensure!(
        found.len() == 1,
        "expected one supported declaration `{name}`, found {}",
        found.len()
    );
    Ok(found.remove(0))
}

fn read_source(root: &Path, target: &str) -> Result<(String, String)> {
    let (file, name) = target
        .rsplit_once(':')
        .context("expected path:Declaration")?;
    let mut relative = std::path::PathBuf::from(file);
    ensure!(
        !file.is_empty()
            && relative
                .components()
                .all(|c| matches!(c, Component::Normal(_))),
        "Lean path must be relative without traversal"
    );
    if relative.extension().is_none() {
        relative.set_extension("lean");
    }
    ensure!(
        relative.extension().is_some_and(|e| e == "lean"),
        "expected a .lean file"
    );
    let canonical_root = root.canonicalize().context("Lean source directory")?;
    let path = canonical_root
        .join(&relative)
        .canonicalize()
        .with_context(|| format!("Lean file {file}"))?;
    ensure!(
        path.starts_with(&canonical_root),
        "Lean source escapes configured directory"
    );
    let source = std::fs::read_to_string(path)?;
    Ok((source, name.to_owned()))
}

/// Raw source associated with one authored unit citation. `source` retains the
/// surrounding module (imports, namespaces, and section variables); `selected`
/// is the exact declaration or case shown by the book. Neither is elaborated.
#[derive(Clone, Debug)]
pub struct LeanSelection {
    pub path: std::path::PathBuf,
    pub source: String,
    pub selected: String,
}

/// Resolve a citation with the same declaration-kind checks as the renderer.
pub fn select(root: &Path, target: &str, kind: crate::units::UnitKind) -> Result<LeanSelection> {
    use crate::units::UnitKind;
    let (source, name) = read_source(root, target)?;
    let selected = match kind {
        UnitKind::Definition => extract_definition(&source, &name),
        UnitKind::Theorem | UnitKind::Lemma => extract_theorem(&source, &name),
        UnitKind::Example => extract_example(&source, &name),
        UnitKind::Grammar => extract(&source, &name),
        UnitKind::Judgment => extract(&source, &name).and_then(|declaration| {
            ensure!(
                declaration.starts_with("inductive "),
                "judgment citation must select an inductive declaration"
            );
            Ok(declaration)
        }),
        UnitKind::Rule => {
            let (name, case) = name
                .rsplit_once('.')
                .context("rule expects path:Judgment.constructor")?;
            extract(&source, name).and_then(|declaration| extract_case(&declaration, case))
        }
        // An obligation may cite a predicate or an unfinished theorem. This
        // selection never promotes an obligation into a proved claim.
        UnitKind::Obligation => {
            extract_definition(&source, &name).or_else(|_| extract_theorem(&source, &name))
        }
    }
    .with_context(|| target.to_owned())?;
    let (file, _) = target
        .rsplit_once(':')
        .context("expected path:Declaration")?;
    let mut relative = std::path::PathBuf::from(file);
    if relative.extension().is_none() {
        relative.set_extension("lean");
    }
    // read_source already checks canonical containment, including symlinks.
    let path = root.join(relative).canonicalize()?;
    Ok(LeanSelection {
        path,
        source,
        selected,
    })
}

pub(crate) fn selected_source(
    root: &Path,
    targets: &[String],
    kind: crate::units::UnitKind,
) -> Result<String> {
    let mut output = String::new();
    for target in targets {
        let selection = select(root, target, kind)?;
        output.push_str(&format!(
            "<figcaption>{}</figcaption><pre><code class=\"language-lean\">{}</code></pre>",
            crate::escape(target),
            highlighted(&selection.selected)?
        ));
    }
    Ok(output)
}

fn highlighted(declaration: &str) -> Result<String> {
    let masked = mask(declaration)?;
    let keywords = regex::Regex::new(
        r"\b(inductive|structure|abbrev|def|theorem|where|deriving|example|by|let|have|show|exact)\b",
    )?;
    let mut html = String::new();
    let mut last = 0;
    for m in keywords.find_iter(&masked) {
        html.push_str(&crate::escape(&declaration[last..m.start()]));
        html.push_str(&format!(
            "<span class=\"lean-keyword\">{}</span>",
            &declaration[m.range()]
        ));
        last = m.end();
    }
    html.push_str(&crate::escape(&declaration[last..]));
    Ok(html.replace('\n', "&#10;"))
}

fn valid_anchor_name(name: &str) -> bool {
    name.as_bytes()
        .first()
        .is_some_and(u8::is_ascii_alphanumeric)
        && name
            .bytes()
            .all(|c| c.is_ascii_alphanumeric() || matches!(c, b'_' | b'.' | b'-'))
}

fn has_definition_body(code: &str) -> bool {
    let mut delimiters = Vec::new();
    let mut chars = code.chars().peekable();
    while let Some(c) = chars.next() {
        match c {
            '(' | '{' | '[' | '⦃' => delimiters.push(c),
            ')' | '}' | ']' | '⦄' => {
                delimiters.pop();
            }
            ':' if delimiters.is_empty() && chars.peek() == Some(&'=') => return true,
            _ => {}
        }
    }
    false
}

// In addition to `:=`, a named definition can use a structure literal's
// `where` or equations. This is a source-style check, not Lean elaboration:
// equation arms start on indented lines and put `=>` on their first line.
// In particular, default binder values do not supply a declaration body.
fn has_named_definition_body(code: &str) -> Result<bool> {
    if has_definition_body(code) {
        return Ok(true);
    }
    let mut delimiters = Vec::new();
    for (offset, c) in code.char_indices() {
        match c {
            '(' | '{' | '[' | '⦃' => delimiters.push(c),
            ')' | '}' | ']' | '⦄' => {
                delimiters.pop();
            }
            'w' if delimiters.is_empty()
                && !follows_identifier(code, offset)
                && code[offset..].starts_with("where")
                && !code[offset + "where".len()..]
                    .chars()
                    .next()
                    .is_some_and(|c| c.is_alphanumeric() || matches!(c, '_' | '\'')) =>
            {
                return Ok(true);
            }
            '|' if delimiters.is_empty()
                && code[..offset]
                    .rsplit_once('\n')
                    .is_some_and(|(_, prefix)| !prefix.is_empty() && prefix.trim().is_empty()) =>
            {
                let arm = code[offset..].lines().next().unwrap_or("");
                ensure!(
                    arm.contains("=>"),
                    "equation arms must put `=>` on their first line"
                );
                return Ok(true);
            }
            _ => {}
        }
    }
    Ok(false)
}

fn command_pattern() -> Result<regex::Regex> {
    Ok(regex::Regex::new(
        r"(?m)^[ \t]*(?:@\[|#|(?:(?:private|protected|noncomputable|unsafe|partial|nonrec|local|scoped)[ \t]+)*(?:example|def|theorem|lemma|abbrev|opaque|axiom|constant|constants|inductive|structure|class|instance|namespace|section|end|variable|variables|universe|universes|import|open|export|attribute|macro|macro_rules|syntax|elab|elab_rules|notation|infix|infixl|infixr|prefix|postfix|initialize|builtin_initialize|mutual)(?:[ \t(:{\[]|$))",
    )?)
}

fn extract_example(source: &str, name: &str) -> Result<String> {
    ensure!(
        valid_anchor_name(name),
        "invalid Lean example anchor `{name}`"
    );
    let (masked, comments) = mask_and_comments(source)?;
    let mut names = HashSet::new();
    let mut open = None;
    let mut selected = None;
    for offset in comments {
        let line_start = source[..offset].rfind('\n').map_or(0, |n| n + 1);
        if !source[line_start..offset].trim().is_empty() {
            continue;
        }
        let line_end = source[offset..]
            .find('\n')
            .map_or(source.len(), |n| offset + n);
        let comment = source[offset + 2..line_end].trim();
        let (end, anchor) = if let Some(anchor) = comment.strip_prefix("ANCHOR:") {
            (false, anchor.trim())
        } else if let Some(anchor) = comment.strip_prefix("ANCHOR_END:") {
            (true, anchor.trim())
        } else {
            continue;
        };
        ensure!(
            valid_anchor_name(anchor),
            "invalid Lean example anchor `{anchor}`"
        );
        if end {
            let (opened, start) = open.take().with_context(|| {
                format!("Lean example anchor `{anchor}` ends without a matching start")
            })?;
            ensure!(
                opened == anchor,
                "Lean example anchor `{opened}` ends with mismatched `{anchor}`"
            );
            if anchor == name {
                selected = Some((start..line_start, (line_end + 1).min(source.len())));
            }
        } else {
            ensure!(open.is_none(), "nested Lean example anchor `{anchor}`");
            ensure!(
                names.insert(anchor),
                "duplicate Lean example anchor `{anchor}`"
            );
            open = Some((anchor, (line_end + 1).min(source.len())));
        }
    }
    if let Some((anchor, _)) = open {
        anyhow::bail!("unterminated Lean example anchor `{anchor}`");
    }
    let (range, after) =
        selected.with_context(|| format!("missing Lean example anchor `{name}`"))?;
    if let Some(next) = masked[after..].lines().find(|line| !line.trim().is_empty()) {
        ensure!(
            !next.starts_with(char::is_whitespace),
            "Lean example anchor `{name}` ends before an indented continuation; place the end marker after the complete example and start the next command at column zero"
        );
    }
    let mut lines = masked[range.clone()]
        .lines()
        .filter(|line| !line.trim().is_empty());
    let header = lines
        .next()
        .with_context(|| format!("Lean example anchor `{name}` is empty"))?;
    let keyword = header
        .split(|c: char| c.is_whitespace() || matches!(c, ':' | '(' | '{' | '['))
        .next();
    ensure!(
        keyword == Some("example"),
        "Lean example anchor `{name}` must contain a column-zero anonymous `example`"
    );
    ensure!(
        lines.all(|line| line.starts_with(char::is_whitespace)),
        "Lean example anchor `{name}` must contain exactly one `example`; continuation lines must be indented"
    );
    // Lean allows sibling commands to be indented. Indentation alone therefore
    // cannot establish that a marked span contains only the selected example.
    // This restricted source style excludes command declarations inside proofs.
    let command = command_pattern()?;
    let declaration_count = command.find_iter(&masked[range.clone()]).count();
    let example_count = regex::Regex::new(r"\bexample\b")?
        .find_iter(&masked[range.clone()])
        .count();
    ensure!(
        declaration_count == 1 && example_count == 1,
        "Lean example anchor `{name}` must contain exactly one `example` and no other commands, even when indented"
    );
    ensure!(
        has_definition_body(&masked[range.clone()]),
        "Lean example anchor `{name}` must include the example body (`:=`)"
    );
    // Preserve code indentation while excluding surrounding blank lines and the
    // anchor markers. Comments documenting the example remain visible.
    Ok(source[range].trim_matches(['\n', '\r']).to_owned())
}

/// Select a marked anonymous Lean example and render its cited source.
/// This checks the marker structure, not Lean elaboration or prose agreement.
pub fn example_source(root: &Path, target: &str) -> Result<String> {
    let (source, anchor) = read_source(root, target)?;
    let example = extract_example(&source, &anchor).with_context(|| target.to_owned())?;
    Ok(format!(
        "<figcaption>{}</figcaption><pre><code class=\"language-lean\">{}</code></pre>",
        crate::escape(target),
        highlighted(&example)?
    ))
}

/// Select exactly one named theorem, preserving its statement and complete proof.
/// Theorem and lemma Markdown blocks share this source-selection contract.
pub fn theorem_source(root: &Path, target: &str) -> Result<String> {
    let (source, name) = read_source(root, target)?;
    let theorem = extract_theorem(&source, &name).with_context(|| target.to_owned())?;
    Ok(format!(
        "<figcaption>{}</figcaption><pre><code class=\"language-lean\">{}</code></pre>",
        crate::escape(target),
        highlighted(&theorem)?
    ))
}

/// Select the complete declarations associated with an authored definition.
/// Citations name declarations literally; enclosing namespaces are not inferred.
pub fn definition_source(root: &Path, targets: &str) -> Result<String> {
    let targets: Vec<_> = targets.split_whitespace().collect();
    ensure!(
        !targets.is_empty(),
        "definition requires at least one opening-line citation"
    );
    let mut output = String::new();
    for target in targets {
        let (source, name) = read_source(root, target)?;
        let declaration = extract_definition(&source, &name).with_context(|| target.to_owned())?;
        output.push_str(&format!(
            "<figcaption>{}</figcaption><pre><code class=\"language-lean\">{}</code></pre>",
            crate::escape(target),
            highlighted(&declaration)?
        ));
    }
    Ok(output)
}

fn selector(rendered: &str, source: &str, group: &str, label: &str) -> String {
    let selector = crate::selector_header(label, None, group, "grammar", "Lean");
    format!("<figure class=\"lean-declaration lean-group\">{selector}<div class=\"lean-grammar\">{rendered}</div><div class=\"lean-source\">{source}<p>Imports, namespaces and section variables remain in the source file.</p></div></figure>")
}

// Select constructor source by its name and indentation, without interpreting
// its binders, premises, or result. Nested match alternatives are not cases.
fn extract_case(declaration: &str, case: &str) -> Result<String> {
    ensure!(
        !case.is_empty() && case.chars().all(|c| c.is_alphanumeric() || c == '_'),
        "use a simple constructor name"
    );
    let masked = mask(declaration)?;
    let header = declaration
        .lines()
        .next()
        .context("missing declaration header")?;
    ensure!(
        header.starts_with("inductive "),
        "rule citation must select an inductive constructor"
    );
    let mut offset = 0;
    let mut candidates = Vec::new();
    for line in masked.split_inclusive('\n') {
        let trimmed = line.trim_start();
        let indent = line.len() - trimmed.len();
        if let Some(row) = trimmed.strip_prefix('|') {
            let name = row
                .trim_start()
                .split(|c: char| c.is_whitespace() || matches!(c, ':' | '(' | '{' | '['))
                .next()
                .unwrap_or("");
            candidates.push((offset, indent, name));
        }
        offset += line.len();
    }
    let indent = candidates
        .iter()
        .map(|(_, indent, _)| *indent)
        .min()
        .context("inductive has no constructors")?;
    let cases: Vec<_> = candidates
        .into_iter()
        .filter(|(_, i, _)| *i == indent)
        .collect();
    let found: Vec<_> = cases
        .iter()
        .enumerate()
        .filter(|(_, (_, _, n))| *n == case)
        .collect();
    ensure!(
        found.len() == 1,
        "expected one constructor `{case}`, found {}",
        found.len()
    );
    let (index, (start, _, _)) = found[0];
    let end = cases
        .get(index + 1)
        .map(|(start, _, _)| *start)
        .unwrap_or(declaration.len());
    // A comment introducing the next declaration is not part of this case.
    let end = masked[..end].trim_end().len();
    Ok(format!("{header}\n{}", declaration[*start..end].trim_end()))
}

/// Which source selections accompany an authored mathematical block.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum View {
    Grammar,
    Judgment,
    Rule,
}

/// Check source citations and pair authored LaTeX with those source excerpts.
/// No mathematical syntax is generated from, or compared with, the Lean source.
pub fn render_authored(
    root: &Path,
    targets: &str,
    body: &str,
    view: View,
    group: &str,
) -> Result<String> {
    let targets: Vec<_> = targets.split_whitespace().collect();
    ensure!(!targets.is_empty(), "expected Lean citations on the directive opening line; use ```{{grammar}} path:Name with authored LaTeX in the body");
    ensure!(
        view == View::Grammar || targets.len() == 1,
        "judgment and rule directives require exactly one opening-line citation"
    );
    ensure!(
        !body.trim().is_empty(),
        "authored math directive requires a LaTeX body"
    );
    let mut source = String::new();
    for target in targets {
        let (file, selected) = read_source(root, target)?;
        let (name, case) = if view == View::Rule {
            let (name, case) = selected
                .rsplit_once('.')
                .context("rule expects path:Judgment.constructor")?;
            (name, Some(case))
        } else {
            (selected.as_str(), None)
        };
        let declaration = extract(&file, name).with_context(|| target.to_owned())?;
        ensure!(
            !matches!(view, View::Judgment | View::Rule) || declaration.starts_with("inductive "),
            "judgment and rule citations must select inductive declarations"
        );
        let declaration = if let Some(case) = case {
            extract_case(&declaration, case)?
        } else {
            declaration
        };
        source.push_str(&format!(
            "<figcaption>{}</figcaption><pre><code class=\"language-lean\">{}</code></pre>",
            crate::escape(target),
            highlighted(&declaration)?
        ));
    }
    // Keep blank lines inside the raw HTML block so Markdown cannot reinterpret
    // the authored TeX. Escaping also keeps TeX text from becoming HTML markup.
    let tex = crate::escape(body.trim()).replace('\n', "&#10;");
    let rendered = format!("<div class=\"math-display\">\\[{tex}\\]</div>");
    let label = match view {
        View::Grammar => "Grammar",
        View::Judgment => "Judgment",
        View::Rule => "Rule",
    };
    Ok(selector(&rendered, &source, group, label))
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn definitions_select_complete_equations_structure_literals_and_multiline_bodies() {
        let source = "namespace Outer\ndef State.initial : State Primitive :=\n  .state FiniteMap.empty FiniteMap.empty\ndef readSlot : State Primitive → Place → Option Slot\n  | .state _ variables, .variable id => variables.lookup id\n  | .state objects _, .field id name => do\n      let .aggregate fields ← objects.lookup id | none\n      fields.lookup name\ndef empty : Store where\n  entries := []\n  uniqueKeys := by\n    exact List.nodup_nil\nabbrev Value\n    (α : Type) :=\n  Option α\nend Outer\n";
        assert_eq!(
            extract_definition(source, "State.initial").unwrap(),
            "def State.initial : State Primitive :=\n  .state FiniteMap.empty FiniteMap.empty"
        );
        let read = extract_definition(source, "readSlot").unwrap();
        assert!(read.contains("  | .state _ variables"));
        assert!(read.ends_with("      fields.lookup name"));
        assert!(!read.contains("def empty"));
        assert!(extract_definition(source, "empty")
            .unwrap()
            .ends_with("    exact List.nodup_nil"));
        assert!(extract_definition(source, "Value")
            .unwrap()
            .ends_with("  Option α"));
        assert!(extract_definition(source, "initial").is_err());
        assert!(extract_definition(source, "Outer.State.initial").is_err());
        // The math-only grammar directive retains its original type contract.
        assert!(extract(source, "readSlot").is_err());
        assert!(extract(source, "Value").is_err());
        for source in [
            "structure Foo where\n  n : Nat",
            "inductive Foo where\n  | zero\n  | succ (previous : Foo)",
            "abbrev Foo := Nat",
        ] {
            assert_eq!(extract_definition(source, "Foo").unwrap(), source);
        }
    }

