use anyhow::{bail, ensure, Context, Result};
use pulldown_cmark::{CodeBlockKind, Event, Parser, Tag, TagEnd};
use regex::Regex;
use serde_json::Value;
use std::{collections::BTreeMap, ops::Range, path::Path};

pub fn escape(s: &str) -> String {
    s.replace('&', "&amp;")
        .replace('<', "&lt;")
        .replace('>', "&gt;")
        .replace('"', "&quot;")
        .replace('\'', "&#39;")
}

// Markdown otherwise consumes TeX row breaks and rewrites primes via smart
// punctuation. Protect explicit math before any roles or directives are parsed.
// The doubled delimiter backslashes are the book's Markdown authoring spelling;
// the HTML text passed to MathJax contains ordinary single-backslash delimiters.
fn protect_math(source: &str) -> String {
    let literal: Vec<_> = Parser::new(source)
        .into_offset_iter()
        .filter_map(|(event, range)| match event {
            Event::Start(
                Tag::CodeBlock(_) | Tag::HtmlBlock | Tag::Link { .. } | Tag::Image { .. },
            )
            | Event::Code(_)
            | Event::Html(_)
            | Event::InlineHtml(_) => Some(range),
            _ => None,
        })
        .collect();
    let mut output = String::new();
    let mut end = 0;
    for (start, _) in source.match_indices(r"\\") {
        if start < end
            || source[..start].ends_with('\\')
            || literal.iter().any(|range| range.contains(&start))
        {
            continue;
        }
        let (display, closing) = match source.as_bytes().get(start + 2) {
            Some(b'[') => (true, r"\\]"),
            Some(b'(') => (false, r"\\)"),
            _ => continue,
        };
        let body_start = start + 3;
        let Some(close) = source[body_start..].find(closing).map(|i| body_start + i) else {
            continue;
        };
        if literal.iter().any(|range| range.contains(&close)) {
            continue;
        }
        let body = &source[body_start..close];
        output.push_str(&source[end..start]);
        if display {
            let tex = escape(body).replace('\n', "&#10;");
            output.push_str(&format!(
                "\n\n<div class=\"math-display\">\\[{tex}\\]</div>\n\n"
            ));
        } else {
            // Inline HTML does not suppress Markdown parsing of its contents.
            // Entities keep every TeX punctuation character out of that parser.
            let tex: String = format!("\\({body}\\)")
                .chars()
                .map(|c| {
                    if c.is_alphanumeric() || c == ' ' {
                        c.to_string()
                    } else {
                        format!("&#{};", u32::from(c))
                    }
                })
                .collect();
            output.push_str(&format!("<span class=\"math-inline\">{tex}</span>"));
        }
        end = close + closing.len();
    }
    output.push_str(&source[end..]);
    output
}

#[derive(Debug)]
struct Role {
    range: Range<usize>,
    id: String,
    definition: bool,
    label: Option<&'static str>,
    lean: bool,
}

// Use Markdown's source ranges to recognize roles, leaving code examples, links,
// escaped text, and HTML blocks alone. The role body is a single-backtick code span.
fn roles(source: &str) -> Result<Vec<Role>> {
    let id_pattern = Regex::new(r"^[A-Za-z0-9][A-Za-z0-9_.-]*$")?;
    let mut found = vec![];
    let mut text_end = None;
    let mut excluded = 0;
    for (event, range) in Parser::new(source).into_offset_iter() {
        match event {
            Event::Start(
                Tag::CodeBlock(_) | Tag::Link { .. } | Tag::Image { .. } | Tag::HtmlBlock,
            ) => {
                excluded += 1;
                text_end = None;
            }
            Event::End(TagEnd::CodeBlock | TagEnd::Link | TagEnd::Image | TagEnd::HtmlBlock) => {
                excluded -= 1;
                text_end = None;
            }
            Event::Text(_) if excluded == 0 => text_end = Some(range),
            Event::Code(id) if excluded == 0 => {
                if let Some(previous) = text_end.take() {
                    for (prefix, definition, label, lean) in [
                        ("{anchor}", true, None, false),
                        ("{definition}", true, Some("definition"), false),
                        ("{obligation}", true, Some("proof obligation"), false),
                        ("{anchor-ref}", false, None, false),
                        ("{lean.type}", false, None, true),
                    ] {
                        if previous.end != range.start
                            || !source[previous.clone()].ends_with(prefix)
                        {
                            continue;
                        }
                        let start = range.start - prefix.len();
                        if source[..start].ends_with('\\') {
                            continue;
                        }
                        // Double-backtick spans are literal demonstrations, not roles.
                        if source[range.clone()] != format!("`{id}`") {
                            continue;
                        }
                        ensure!(lean || id_pattern.is_match(&id), "invalid anchor ID `{id}`");
                        found.push(Role {
                            range: start..range.end,
                            id: id.into_string(),
                            definition,
                            label,
                            lean,
                        });
                        break;
                    }
                }
            }
            _ => text_end = None,
        }
    }
    Ok(found)
}

#[derive(Clone, Copy)]
enum MarkdownDirective {
    Definition,
    Example,
    Theorem,
    Lemma,
}

impl MarkdownDirective {
    fn parse(name: &str) -> Option<Self> {
        match name {
            "{definition}" => Some(Self::Definition),
            "{example}" => Some(Self::Example),
            "{theorem}" => Some(Self::Theorem),
            "{lemma}" => Some(Self::Lemma),
            _ => None,
        }
    }

    fn name(self) -> &'static str {
        match self {
            Self::Definition => "definition",
            Self::Example => "example",
            Self::Theorem => "theorem",
            Self::Lemma => "lemma",
        }
    }

    fn label(self) -> &'static str {
        match self {
            Self::Definition => "Definition",
            Self::Example => "Example",
            Self::Theorem => "Theorem",
            Self::Lemma => "Lemma",
        }
    }

    fn definition_label(self) -> &'static str {
        match self {
            Self::Definition => "definition",
            Self::Example => "anchor",
            Self::Theorem => "theorem",
            Self::Lemma => "lemma",
        }
    }
}

struct DirectiveBlock {
    range: Range<usize>,
    info: String,
    body: String,
}

fn directive_blocks(source: &str) -> Vec<DirectiveBlock> {
    let mut found = vec![];
    let mut block = None;
    for (event, range) in Parser::new(source).into_offset_iter() {
        match event {
            Event::Start(Tag::CodeBlock(CodeBlockKind::Fenced(info)))
                if [
                    "{heap}",
                    "{grammar}",
                    "{judgment}",
                    "{rule}",
                    "{definition}",
                    "{theorem}",
                    "{lemma}",
                    "{example}",
                    "{obligation}",
                    "{lean.type}",
                    "{lean.judgment}",
                    "{lean.rule}",
                ]
                .iter()
                .any(|name| info.starts_with(name)) =>
            {
                block = Some(DirectiveBlock {
                    range,
                    info: info.into_string(),
                    body: String::new(),
                });
            }
            Event::Text(text) => {
                if let Some(block) = &mut block {
                    block.body.push_str(&text);
                }
            }
            Event::End(TagEnd::CodeBlock) => {
                if let Some(mut block) = block.take() {
                    block.range.end = range.end;
                    found.push(block);
                }
            }
            _ => {}
        }
    }
    found
}

fn chapter_roles(source: &str) -> Result<Vec<Role>> {
    let protected = protect_math(source);
    let mut found = roles(&protected)?;
    for unit in units::parse(source, "chapter")? {
        found.push(Role {
            range: unit.range,
            id: unit.id,
            definition: true,
            label: None,
            lean: false,
        });
    }
    for block in directive_blocks(&protected) {
        if block
            .info
            .split_whitespace()
            .next()
            .is_some_and(|name| MarkdownDirective::parse(name).is_some() || name == "{obligation}")
        {
            // These bodies are Markdown; grammar, judgment, and rule bodies are TeX.
            ensure!(
                !directive_blocks(&block.body).iter().any(|nested| {
                    ["{definition}", "{example}", "{theorem}", "{lemma}"]
                        .iter()
                        .any(|name| nested.info.starts_with(name))
                }),
                "definition, example, theorem, and lemma directives cannot be nested within one another"
            );
            found.extend(roles(&protect_math(&block.body))?);
        }
    }
    Ok(found)
}

fn render_unit(
    unit: &units::SpecUnit,
    path: &str,
    anchors: &BTreeMap<String, String>,
    lean_root: Option<&Path>,
) -> Result<String> {
    let label = unit.kind.label();
    let lower_label = label.to_ascii_lowercase();
    let role = Role {
        range: unit.range.clone(),
        id: unit.id.clone(),
        definition: true,
        label: None,
        lean: false,
    };
    let heading = render_role(&role, path, anchors, &lower_label)?;
    let (alternate, cited_source) = if !unit.lean.is_empty() {
        let root = lean_root.context("Lean directives require preprocessor.dada.lean-source")?;
        ("Lean", lean::selected_source(root, &unit.lean, unit.kind)?)
    } else if !unit.rust.is_empty() {
        let root = lean_root.and_then(Path::parent).context(
            "Rust citations require a configured Lean source directory within the v2 root",
        )?;
        let mut cited = String::new();
        for target in unit.rust.iter().chain(&unit.tests) {
            let selected = crate::rust_source::select(root, target)?;
            cited.push_str(&format!(
                "<figcaption>{}</figcaption><pre><code class=\"language-rust\">{}</code></pre>",
                escape(target),
                escape(&selected.selected).replace('\n', "&#10;")
            ));
        }
        ("Rust", cited)
    } else {
        ("", String::new())
    };
    let header = if alternate.is_empty() {
        format!("<div class=\"lean-selector\"><div class=\"block-heading\">{heading}</div></div>")
    } else {
        selector_header(
            label,
            Some(&heading),
            &format!("unit-{}", unit.id),
            "rendered",
            alternate,
        )
    };
    let body = if unit.kind.is_math() {
        let tex = escape(unit.body.trim()).replace('\n', "&#10;");
        format!("<div class=\"lean-grammar\"><div class=\"math-display\">\\[{tex}\\]</div></div>")
    } else {
        let body = render(&unit.body, path, anchors, lean_root, &unit.id, &lower_label)?;
        format!(
            "<div class=\"lean-markdown-body\">\n\n{}\n\n</div>",
            body.trim_matches('\n')
        )
    };
    let markdown_class = if unit.kind.is_math() {
        ""
    } else {
        " lean-markdown"
    };
    Ok(format!("\n<figure class=\"lean-declaration lean-group{markdown_class}\">{header}{body}<div class=\"lean-source\">{cited_source}</div></figure>\n\n"))
}

fn walk(chapters: &Value, f: &mut impl FnMut(&Value) -> Result<()>) -> Result<()> {
    if let Some(items) = chapters.as_array() {
        for item in items {
            if let Some(chapter) = item.get("Chapter") {
                f(chapter)?;
                walk(&chapter["sub_items"], f)?;
            }
        }
    }
    Ok(())
}

fn relative_html(from: &str, to: &str) -> Result<String> {
    // mdBook chapter paths are relative to the source directory.
    let parts = |s: &str| -> Result<Vec<String>> {
        Path::new(s)
            .components()
            .map(|c| match c {
                std::path::Component::Normal(p) => Ok(p.to_string_lossy().into_owned()),
                _ => bail!("chapter path must be relative and normalized: {s}"),
            })
            .collect()
    };
    let mut from = parts(from)?;
    from.pop();
    let mut to = parts(to)?;
    let file = to.last_mut().context("empty chapter path")?;
    *file = Path::new(file)
        .with_extension("html")
        .to_string_lossy()
        .into_owned();
    let common = from.iter().zip(&to).take_while(|(a, b)| a == b).count();
    let path = std::iter::repeat_n("..".to_owned(), from.len() - common)
        .chain(to[common..].iter().cloned())
        .collect::<Vec<_>>()
        .join("/");
    Ok(path
        .replace('%', "%25")
        .replace(' ', "%20")
        .replace('#', "%23")
        .replace('?', "%3F"))
}

fn render_role(
    role: &Role,
    path: &str,
    anchors: &BTreeMap<String, String>,
    definition_label: &str,
) -> Result<String> {
    ensure!(
        !role.lean,
        "lean.type has been replaced: use ```{{grammar}} path:Name with authored LaTeX in the body"
    );
    let target = anchors
        .get(&role.id)
        .with_context(|| format!("unknown anchor `{}`", role.id))?;
    let fragment = format!("claim-{}", role.id);
    let href = if target == path {
        format!("#{fragment}")
    } else {
        format!("{}#{fragment}", relative_html(path, target)?)
    };
    let id_attr = if role.definition {
        format!(" id=\"{fragment}\"")
    } else {
        String::new()
    };
    let label = if role.definition {
        role.label.unwrap_or(definition_label)
    } else {
        "ref"
    };
    Ok(format!(
        "<a{id_attr} class=\"spec-shield\" href=\"{}\" aria-label=\"{label}: {}\"><span class=\"spec-shield-label\">{label}</span><span class=\"spec-shield-name\">{}</span></a>",
        escape(&href), escape(&role.id), escape(&role.id)
    ))
}

// Only a sequence of declaration roles at the very start belongs in the header.
// Roles later in prose, inside literals, or inside nested directives stay put.
fn markdown_heading<'a>(
    source: &'a str,
    path: &str,
    anchors: &BTreeMap<String, String>,
    definition_label: &str,
) -> Result<(String, &'a str)> {
    let protected = protect_math(source);
    let mut heading = Vec::new();
    let mut end = 0;
    for role in roles(&protected)? {
        if !protected[end..role.range.start].trim().is_empty()
            || !role.definition
            || role.label == Some("proof obligation")
        {
            break;
        }
        heading.push(render_role(&role, path, anchors, definition_label)?);
        // A promoted role is preceded only by whitespace and other roles, so
        // math protection has not changed its source offsets.
        end = role.range.end;
    }
    Ok((heading.join(" "), &source[end..]))
}

/// Shared header for every rendered/source pair. The heading is generated HTML;
/// labels, group names, and radio values are escaped here.
pub(crate) fn selector_header(
    label: &str,
    heading: Option<&str>,
    group: &str,
    rendered_value: &str,
    alternate: &str,
) -> String {
    let label = escape(label);
    let fallback = format!("<span class=\"block-label\">{label}</span>");
    let heading = heading.unwrap_or(&fallback);
    let group = escape(group);
    let rendered_value = escape(rendered_value);
    let alternate_value = escape(&alternate.to_ascii_lowercase());
    let alternate = escape(alternate);
    format!("<div class=\"lean-selector\" role=\"group\" aria-label=\"{label} view\"><div class=\"block-heading\">{heading}</div><div class=\"view-options\"><label><input type=\"radio\" name=\"{group}\" value=\"{rendered_value}\" checked> Rendered</label><label><input type=\"radio\" name=\"{group}\" value=\"{alternate_value}\"> {alternate}</label></div></div>")
}

fn render(
    source: &str,
    path: &str,
    anchors: &BTreeMap<String, String>,
    lean_root: Option<&Path>,
    scope: &str,
    definition_label: &str,
) -> Result<String> {
    let protected = protect_math(source);
    let source = protected.as_str();
    let structured_units = units::parse(source, path)?;
    let mut edits = vec![];
    for role in roles(source)? {
        let rendered = render_role(&role, path, anchors, definition_label)?;
        edits.push((role.range, rendered));
    }
    for (event, range) in Parser::new(source).into_offset_iter() {
        if matches!(event, Event::Start(Tag::Paragraph)) {
            ensure!(
                !source[range.clone()].starts_with("{example} "),
                "the paragraph {{example}} marker has been replaced: use a fenced ```{{example}} path:anchor with a Markdown body and a Lean test, or label an unfinished scenario as informational"
            );
            if source[range.clone()].starts_with("{informational} ") {
                edits.push((
                    range.start..range.start + "{informational}".len(),
                    "<span class=\"informational-label\">Informational</span>".to_owned(),
                ));
            }
        }
    }

    for block in directive_blocks(source) {
        if let Some(unit) = structured_units
            .iter()
            .find(|unit| unit.range.start == block.range.start)
        {
            for dependency in &unit.uses {
                ensure!(
                    anchors.contains_key(dependency),
                    "unknown unit dependency `{dependency}`"
                );
            }
            edits.push((block.range, render_unit(unit, path, anchors, lean_root)?));
            continue;
        }
        let start = block.range.start;
        let kind = block.info;
        let facts = block.body;
        let (directive, argument) = kind.split_once(char::is_whitespace).unwrap_or((&kind, ""));
        ensure!(
            ![
                "{heap}",
                "{grammar}",
                "{rule}",
                "{judgment}",
                "{definition}",
                "{theorem}",
                "{lemma}",
                "{example}"
            ]
            .iter()
            .any(|name| directive.starts_with(name) && directive != *name),
            "separate the directive name and citation with whitespace"
        );
        ensure!(!matches!(directive, "{lean.type}" | "{lean.judgment}" | "{lean.rule}"),
                        "{directive} has been replaced: use ```{{grammar}} path:Name, ```{{judgment}} path:Name, or ```{{rule}} path:Name.case with authored LaTeX in the body");
        let id = format!("{scope}-{start}");
        if let Some(markdown) = MarkdownDirective::parse(directive) {
            let name = markdown.name();
            let label = markdown.label();
            let citations = argument.split_whitespace().count();
            if matches!(markdown, MarkdownDirective::Definition) {
                ensure!(
                    citations > 0,
                    "definition requires at least one opening-line citation"
                );
            } else {
                ensure!(
                    citations == 1,
                    "{name} requires exactly one opening-line citation"
                );
            }
            ensure!(!facts.trim().is_empty(), "{name} requires a Markdown body");
            let root =
                lean_root.context("Lean directives require preprocessor.dada.lean-source")?;
            let lean_source = match markdown {
                MarkdownDirective::Definition => lean::definition_source(root, argument)?,
                MarkdownDirective::Example => lean::example_source(root, argument.trim())?,
                MarkdownDirective::Theorem | MarkdownDirective::Lemma => {
                    lean::theorem_source(root, argument.trim())?
                }
            };
            let heading_label = if matches!(markdown, MarkdownDirective::Example) {
                "example"
            } else {
                markdown.definition_label()
            };
            let (heading, body) = markdown_heading(&facts, path, anchors, heading_label)?;
            ensure!(
                !body.trim().is_empty(),
                "{name} requires a Markdown body after its heading anchors"
            );
            let body = render(
                body,
                path,
                anchors,
                lean_root,
                &id,
                markdown.definition_label(),
            )?;
            let selector = selector_header(
                label,
                (!heading.is_empty()).then_some(heading.as_str()),
                &format!("{name}-{id}"),
                "rendered",
                "Lean",
            );
            // Blank lines terminate raw HTML blocks so mdBook renders the body
            // as Markdown, including its explicit math delimiters and proof prose.
            edits.push((block.range, format!(
                "\n<figure class=\"lean-declaration lean-group lean-markdown lean-{name}\">{selector}<div class=\"lean-markdown-body\">\n\n{}\n\n</div><div class=\"lean-source\">{lean_source}</div></figure>\n\n",
                body.trim_matches('\n')
            )));
            continue;
        }
        let view = match directive {
            "{grammar}" => Some(lean::View::Grammar),
            "{judgment}" => Some(lean::View::Judgment),
            "{rule}" => Some(lean::View::Rule),
            _ => None,
        };
        if let Some(view) = view {
            let root =
                lean_root.context("Lean directives require preprocessor.dada.lean-source")?;
            edits.push((
                block.range,
                format!(
                    "\n{}\n",
                    lean::render_authored(root, argument.trim(), &facts, view, &id)?
                ),
            ));
            continue;
        }
        ensure!(
            argument.trim().is_empty(),
            "{directive} does not accept opening-line arguments"
        );
        let graph = graph::render(&facts)?;
        let selector = selector_header("Diagram", None, &format!("heap-{id}"), "rendered", "Facts");
        let source = escape(&facts).replace('\n', "&#10;");
        edits.push((block.range, format!("\n<figure class=\"heap-figure\">{selector}{graph}<pre class=\"heap-facts\"><code>{source}</code></pre></figure>\n")));
    }
    edits.sort_by_key(|(range, _)| range.start);
    let mut result = String::new();
    let mut end = 0;
    for (range, replacement) in edits {
        ensure!(range.start >= end, "overlapping markup");
        result.push_str(&source[end..range.start]);
        result.push_str(&replacement);
        end = range.end;
    }
    result.push_str(&source[end..]);
    Ok(result)
}

pub fn process(book: &mut Value) -> Result<()> {
    process_with_lean(book, None)
}

pub fn process_with_lean(book: &mut Value, lean_root: Option<&Path>) -> Result<()> {
    let key = if book.get("items").is_some_and(Value::is_array) {
        "items"
    } else if book.get("sections").is_some_and(Value::is_array) {
        "sections"
    } else {
        bail!("unsupported mdBook input: expected an items or sections array");
    };
    let mut anchors = BTreeMap::new();
    walk(&book[key], &mut |chapter| {
        let source = chapter["content"]
            .as_str()
            .context("chapter has no content")?;
        let path = chapter["path"].as_str().context("chapter has no path")?;
        lint::check_latex(source, path)?;
        for role in chapter_roles(source).with_context(|| path.to_owned())? {
            if role.definition {
                if let Some(previous) = anchors.insert(role.id.clone(), path.to_owned()) {
                    bail!("duplicate anchor `{}` in {previous} and {path}", role.id);
                }
            }
        }
        Ok(())
    })?;
    fn update(
        items: &mut Value,
        anchors: &BTreeMap<String, String>,
        lean_root: Option<&Path>,
    ) -> Result<()> {
        if let Some(items) = items.as_array_mut() {
            for item in items {
                if let Some(chapter) = item.get_mut("Chapter") {
                    let path = chapter["path"].as_str().context("chapter has no path")?;
                    let source = chapter["content"]
                        .as_str()
                        .context("chapter has no content")?;
                    let content = render(source, path, anchors, lean_root, path, "anchor")
                        .with_context(|| format!("chapter {path}"))?;
                    chapter["content"] = Value::String(content);
                    update(&mut chapter["sub_items"], anchors, lean_root)?;
                }
            }
        }
        Ok(())
    }
    update(&mut book[key], &anchors, lean_root)
}

//! Source-level LaTeX conventions, including literal examples in Markdown.

use anyhow::{ensure, Result};
use regex::Regex;

/// Require an opening group immediately before each overbar command and a
/// literal space immediately after it. Longer TeX control words are separate commands.
pub fn check_latex(source: &str, path: &str) -> Result<()> {
    let overline = Regex::new(r"\\overline([^A-Za-z]|$)")?;
    for matched in overline.captures_iter(source) {
        let command = matched.get(0).expect("a regex match has a full capture");
        let line = source[..command.start()]
            .bytes()
            .filter(|&byte| byte == b'\n')
            .count()
            + 1;
        ensure!(
            source[..command.start()].ends_with('{') && &matched[1] == " ",
            "{path}:{line}: LaTeX style: use {{\\overline f}}; the command must be immediately preceded by `{{` and immediately followed by a literal space"
        );
    }
    Ok(())
}

use anyhow::{ensure, Result};
use std::io;

fn main() -> Result<()> {
    let args: Vec<_> = std::env::args().skip(1).collect();
    if args.first().is_some_and(|a| a == "supports") {
        std::process::exit(if args.get(1).is_some_and(|a| a == "html") {
            0
        } else {
            1
        });
    }
    ensure!(args.is_empty(), "usage: mdbook-dada [supports html]");
    let (context, mut book): (serde_json::Value, serde_json::Value) =
        serde_json::from_reader(io::stdin())?;
    ensure!(
        context["renderer"] == "html",
        "only the HTML renderer is supported"
    );
    let lean_root = context["config"]["preprocessor"]["dada"]["lean-source"]
        .as_str()
        .map(|p| std::path::Path::new(context["root"].as_str().unwrap_or(".")).join(p));
    mdbook_dada::process_with_lean(&mut book, lean_root.as_deref())?;
    serde_json::to_writer(io::stdout(), &book)?;
    Ok(())
}

//! Rectilinear routing on corridors around node rectangles.
use anyhow::{Context, Result};
use std::{cmp::Reverse, collections::BinaryHeap};

type Point = (i64, i64);
pub type Rect = (i64, i64, i64, i64);

fn clear(a: Point, b: Point, boxes: &[Rect]) -> bool {
    !boxes.iter().any(|&(x, y, w, h)| {
        if a.0 == b.0 {
            a.0 > x && a.0 < x + w && a.1.min(b.1) < y + h && a.1.max(b.1) > y
        } else {
            a.1 > y && a.1 < y + h && a.0.min(b.0) < x + w && a.0.max(b.0) > x
        }
    })
}

pub fn route(start: Point, end: Point, boxes: &[Rect]) -> Result<Vec<Point>> {
    let mut xs = vec![start.0, end.0];
    let mut ys = vec![start.1, end.1];
    for &(x, y, w, h) in boxes {
        xs.extend([x - 20, x + w + 20]);
        ys.extend([y - 20, y + h + 20]);
    }
    xs.sort_unstable();
    xs.dedup();
    ys.sort_unstable();
    ys.dedup();
    let nx = xs.len();
    let index = |p: Point| -> Result<usize> {
        Ok(
            ys.binary_search(&p.1).ok().context("missing routing y")? * nx
                + xs.binary_search(&p.0).ok().context("missing routing x")?,
        )
    };
    let point = |i: usize| (xs[i % nx], ys[i / nx]);
    let initial = index(start)? * 2;
    let goal = index(end)?;
    let mut costs = vec![i64::MAX; nx * ys.len() * 2];
    let mut previous = vec![None; costs.len()];
    costs[initial] = 0;
    let mut queue = BinaryHeap::from([Reverse((0, initial))]);
    while let Some(Reverse((cost, state))) = queue.pop() {
        if cost != costs[state] {
            continue;
        }
        let node = state / 2;
        if node == goal {
            let mut path = vec![point(node)];
            let mut current = state;
            while let Some(parent) = previous[current] {
                path.push(point(parent / 2));
                current = parent;
            }
            path.reverse();
            let mut compact: Vec<Point> = Vec::new();
            for p in path {
                while compact.len() >= 2 {
                    let a = compact[compact.len() - 2];
                    let b = compact[compact.len() - 1];
                    if (a.0 == b.0 && b.0 == p.0) || (a.1 == b.1 && b.1 == p.1) {
                        compact.pop();
                    } else {
                        break;
                    }
                }
                compact.push(p);
            }
            return Ok(compact);
        }
        let x = node % nx;
        let y = node / nx;
        let neighbors = [
            (x.checked_sub(1).map(|x| y * nx + x), 0),
            ((x + 1 < nx).then_some(node + 1), 0),
            (y.checked_sub(1).map(|y| y * nx + x), 1),
            ((y + 1 < ys.len()).then_some(node + nx), 1),
        ];
        for (next, direction) in neighbors {
            let Some(next) = next else {
                continue;
            };
            let a = point(node);
            let b = point(next);
            if !clear(a, b, boxes) {
                continue;
            }
            let step =
                (a.0 - b.0).abs() + (a.1 - b.1).abs() + if state % 2 == direction { 0 } else { 25 };
            let next_state = next * 2 + direction;
            if cost + step < costs[next_state] {
                costs[next_state] = cost + step;
                previous[next_state] = Some(state);
                queue.push(Reverse((cost + step, next_state)));
            }
        }
    }
    anyhow::bail!("no obstacle-free diagram route from {start:?} to {end:?}")
}

#[cfg(test)]
mod tests {
    use super::*;
    #[test]
    fn routes_around_boxes_and_through_column_gaps() {
        let boxes = [(100, 0, 80, 80), (100, 140, 80, 80)];
        for (start, end) in [
            ((0, 40), (240, 40)),
            ((0, 110), (240, 110)),
            ((240, 40), (0, 40)),
            ((200, 40), (200, 180)),
        ] {
            let path = route(start, end, &boxes).unwrap();
            assert_eq!(path.first(), Some(&start));
            assert_eq!(path.last(), Some(&end));
            for pair in path.windows(2) {
                assert!(pair[0].0 == pair[1].0 || pair[0].1 == pair[1].1);
                assert!(clear(pair[0], pair[1], &boxes));
            }
        }
        assert_eq!(
            route((0, 110), (240, 110), &boxes).unwrap(),
            vec![(0, 110), (240, 110)]
        );
    }
}

//! Exact source selections for named, unexpanded Rust items.
//!
//! Citations use `relative/file.rs:module::Type::method`. Inline modules are
//! traversed, but external modules and macros are not expanded. Conditional
//! compilation is not evaluated: ambiguous names are rejected even if a build
//! would select just one of them. The complete file is returned as context for
//! selections such as methods whose meaning depends on their enclosing impl.

use std::path::{Component, Path, PathBuf};

use anyhow::{bail, ensure, Context, Result};
use proc_macro2::Span;
use syn::{spanned::Spanned, ImplItem, Item, TraitItem, Type};

/// A source item and the complete file from which it was selected.
#[derive(Clone, Debug)]
pub struct Selection {
    /// Canonical path, guaranteed to remain within the supplied source root.
    pub path: PathBuf,
    pub source: String,
    /// Original source bytes, including the item's attributes and complete body.
    pub selected: String,
    /// Whether this exact item is a free function carrying the built-in test attribute.
    pub is_test: bool,
}

/// Select exactly one named Rust item, without interpreting or executing it.
pub fn select(root: &Path, target: &str) -> Result<Selection> {
    let (file, name) = target
        .split_once(':')
        .with_context(|| format!("Rust citation `{target}` must be `file.rs:Name`"))?;
    let relative = Path::new(file);
    ensure!(
        !relative.as_os_str().is_empty()
            && relative
                .components()
                .all(|part| matches!(part, Component::Normal(_) | Component::CurDir)),
        "Rust citation path `{file}` must be relative and cannot contain `..`"
    );
    ensure!(
        relative
            .extension()
            .is_some_and(|extension| extension == "rs"),
        "Rust citation `{target}` must name a `.rs` file"
    );
    let parsed_name = syn::parse_str::<syn::Path>(name)
        .with_context(|| format!("invalid Rust item name `{name}` in citation `{target}`"))?;
    ensure!(
        parsed_name.leading_colon.is_none()
            && parsed_name
                .segments
                .iter()
                .all(|part| matches!(part.arguments, syn::PathArguments::None)),
        "Rust citation name `{name}` must be an unparameterized item path"
    );
    let root = root
        .canonicalize()
        .with_context(|| format!("cannot locate Rust source root {}", root.display()))?;
    let path = root
        .join(relative)
        .canonicalize()
        .with_context(|| format!("cannot locate Rust source `{file}`"))?;
    ensure!(
        path.starts_with(&root),
        "Rust citation `{target}` escapes its source root through a symlink"
    );
    let source = std::fs::read_to_string(&path)
        .with_context(|| format!("cannot read Rust source {}", path.display()))?;
    let (selected, is_test) = select_source_item(&source, name)
        .with_context(|| format!("cannot select Rust citation `{target}`"))?;
    Ok(Selection {
        path,
        source,
        selected,
        is_test,
    })
}

#[cfg(test)]
fn select_source(source: &str, name: &str) -> Result<String> {
    Ok(select_source_item(source, name)?.0)
}

fn select_source_item(source: &str, name: &str) -> Result<(String, bool)> {
    let file = syn::parse_file(source).context("invalid Rust source")?;
    let mut selections = Vec::new();
    collect_items(&file.items, "", name, &mut selections);
    let (span, is_test) = match selections.as_slice() {
        [] => bail!("no named Rust item `{name}` exists in this file"),
        [selection] => *selection,
        _ => bail!("multiple Rust items named `{name}` exist in this file"),
    };
    source
        .get(span.byte_range())
        .map(|selected| (selected.to_owned(), is_test))
        .context("Rust item span does not identify valid UTF-8 source bytes")
}

fn qualified(prefix: &str, name: impl std::fmt::Display) -> String {
    if prefix.is_empty() {
        name.to_string()
    } else {
        format!("{prefix}::{name}")
    }
}

fn retain_match(
    name: &str,
    target: &str,
    span: Span,
    is_test: bool,
    selections: &mut Vec<(Span, bool)>,
) {
    if name == target {
        selections.push((span, is_test));
    }
}

fn collect_items(items: &[Item], prefix: &str, target: &str, selections: &mut Vec<(Span, bool)>) {
    for item in items {
        let ident = match item {
            Item::Const(item) => Some(&item.ident),
            Item::Enum(item) => Some(&item.ident),
            Item::Fn(item) => Some(&item.sig.ident),
            Item::Macro(item) => item.ident.as_ref(),
            Item::Mod(item) => Some(&item.ident),
            Item::Static(item) => Some(&item.ident),
            Item::Struct(item) => Some(&item.ident),
            Item::Trait(item) => Some(&item.ident),
            Item::TraitAlias(item) => Some(&item.ident),
            Item::Type(item) => Some(&item.ident),
            Item::Union(item) => Some(&item.ident),
            _ => None,
        };
        if let Some(ident) = ident {
            let is_test = match item {
                Item::Fn(function) => function.attrs.iter().any(
                    |attr| matches!(&attr.meta, syn::Meta::Path(path) if path.is_ident("test")),
                ),
                _ => false,
            };
            retain_match(
                &qualified(prefix, ident),
                target,
                item.span(),
                is_test,
                selections,
            );
        }
        match item {
            Item::Mod(module) => {
                if let Some((_, items)) = &module.content {
                    collect_items(items, &qualified(prefix, &module.ident), target, selections);
                }
            }
            Item::Impl(item) => {
                // A path self-type provides an explicit, stable citation name.
                // Generic parameters are omitted, just as in ordinary Rust paths.
                if let Type::Path(self_type) = item.self_ty.as_ref() {
                    if self_type.qself.is_none() {
                        let name = self_type
                            .path
                            .segments
                            .iter()
                            .map(|part| part.ident.to_string())
                            .collect::<Vec<_>>()
                            .join("::");
                        let prefix = qualified(prefix, name);
                        for member in &item.items {
                            let ident = match member {
                                ImplItem::Const(item) => Some(&item.ident),
                                ImplItem::Fn(item) => Some(&item.sig.ident),
                                ImplItem::Type(item) => Some(&item.ident),
                                _ => None,
                            };
                            if let Some(ident) = ident {
                                retain_match(
                                    &qualified(&prefix, ident),
                                    target,
                                    member.span(),
                                    false,
                                    selections,
                                );
                            }
                        }
                    }
                }
            }
            Item::Trait(item) => {
                let prefix = qualified(prefix, &item.ident);
                for member in &item.items {
                    let ident = match member {
                        TraitItem::Const(item) => Some(&item.ident),
                        TraitItem::Fn(item) => Some(&item.sig.ident),
                        TraitItem::Type(item) => Some(&item.ident),
                        _ => None,
                    };
                    if let Some(ident) = ident {
                        retain_match(
                            &qualified(&prefix, ident),
                            target,
                            member.span(),
                            false,
                            selections,
                        );
                    }
                }
            }
            _ => {}
        }
    }
}

