        let source = "mod nested {\n    pub struct Store<T>(T);\n    impl<T> Store<T> {\n        /// Read an entry.\n        pub fn read(&self) -> &T { &self.0 }\n    }\n    #[test]\n    fn checked() {}\n}\n";
        assert_eq!(
