        assert!(select_source(
            "struct T; impl T { fn same() {} } impl Trait for T { fn same() {} }",
            "T::same"
        )
        .is_err());
        assert!(select_source("generate! { fn generated() {} }", "generated").is_err());
        assert!(select_source("fn outer() { fn inner() {} }", "inner").is_err());
    }

